/// Only for a register that declares no master dimension at all - a shape the
/// corpus never shows in this slot - does the older single-field reading apply,
/// and it stays fail-closed on ambiguity there.
#[test]
fn form_navigation_panel_open_by_value_field_reading_is_limited_to_masterless_registers() {
    let register_uuid = "77777777-7777-4777-8777-777777777777".to_string();
    let object_refs = BTreeMap::from([(
        register_uuid.clone(),
        "InformationRegister.Queue".to_string(),
    )]);
    let one_field = BTreeMap::from([(
        register_uuid.clone(),
        vec![InformationRegisterFieldReference {
            field_reference: "InformationRegister.Queue.Dimension.Message".to_string(),
            value_owner_references: BTreeSet::from(["Catalog.OtherOwner".to_string()]),
        }],
    )]);
    assert_eq!(
        form_body::parse_form_command_interface_command_for_test(
            &format!("{{3,{register_uuid}}}"),
            &object_refs,
            &one_field,
            &BTreeMap::new(),
            "Catalog.CurrentOwner",
        ),
        Some("InformationRegister.Queue.StandardCommand.OpenByValue.Message".to_string())
    );

    let ambiguous = BTreeMap::from([(
        register_uuid.clone(),
        ["First", "Second"]
            .into_iter()
            .map(|name| InformationRegisterFieldReference {
                field_reference: format!("InformationRegister.Queue.Dimension.{name}"),
                value_owner_references: BTreeSet::from(["Catalog.OtherOwner".to_string()]),
            })
            .collect(),
    )]);
    assert_eq!(
        form_body::parse_form_command_interface_command_for_test(
            &format!("{{3,{register_uuid}}}"),
            &object_refs,
            &ambiguous,
            &BTreeMap::new(),
            "Catalog.CurrentOwner",
        ),
        None
    );
}

#[test]
fn form_navigation_panel_kind_3_names_catalog_create_based_on() {
    // A catalog names "create based on" from slot 3, where a document or a
    // business process names the same command from slot 2. Layout taken from
    // `{3,<Catalog.Претензии uuid>}` on Catalog.Партнеры's element form, where
    // the platform writes Catalog.Претензии.StandardCommand.CreateBasedOn.
    let catalog_uuid = "aaaaaaaa-1111-4111-8111-111111111111".to_string();
    let document_uuid = "bbbbbbbb-2222-4222-8222-222222222222".to_string();
    let object_refs = BTreeMap::from([
        (catalog_uuid.clone(), "Catalog.Claims".to_string()),
        (document_uuid.clone(), "Document.Invoice".to_string()),
    ]);

    assert_eq!(
        form_body::parse_form_command_interface_command_for_test(
            &format!("{{3,{catalog_uuid}}}"),
            &object_refs,
            &BTreeMap::new(),
            &BTreeMap::new(),
            "Catalog.Partners",
        ),
        Some("Catalog.Claims.StandardCommand.CreateBasedOn".to_string())
    );
    // Slot 2 keeps naming CreateBasedOn for the kinds that use it there.
    assert_eq!(
        form_body::parse_form_command_interface_command_for_test(
            &format!("{{2,{document_uuid}}}"),
            &object_refs,
            &BTreeMap::new(),
            &BTreeMap::new(),
            "Catalog.Partners",
        ),
        Some("Document.Invoice.StandardCommand.CreateBasedOn".to_string())
    );
}

