fn owner_metadata_collection_for_test(marker: &str, items: &[&str]) -> String {
    if items.is_empty() {
        format!("{{{marker},0}}")
    } else {
        format!("{{{marker},{},{}}}", items.len(), items.join(","))
    }
}

