#[test]
fn extracts_command_interface_subsystems_order() {
    let first_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let second_uuid = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let body =
        deflate_for_test(format!("{{7,0,0,0,1,2,{first_uuid},{second_uuid},0,0}}").as_bytes());
    let metadata_refs = BTreeMap::from([
        (
            first_uuid.to_string(),
            MetadataCommandReference {
                kind: "Subsystem".to_string(),
                name: "Sales".to_string(),
                use_standard_commands: true,
            },
        ),
        (
            second_uuid.to_string(),
            MetadataCommandReference {
                kind: "Subsystem".to_string(),
                name: "Purchases".to_string(),
                use_standard_commands: true,
            },
        ),
    ]);

    let command_interface =
        parse_command_interface_blob(&body, &BTreeMap::new(), &metadata_refs).unwrap();
    let xml = format_command_interface_xml(&command_interface);

    assert!(xml.contains("<SubsystemsOrder>"));
    assert!(xml.contains("<Subsystem>Subsystem.Sales</Subsystem>"));
    assert!(xml.contains("<Subsystem>Subsystem.Purchases</Subsystem>"));
    assert!(!xml.contains("<CommandsVisibility>"));
}

#[test]
fn extracts_command_interface_visibility_placement_order_and_groups() {
    let command_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let group_uuid = "1af6d528-0b86-4fba-ab95-bd7475db03ba";
    let body = deflate_for_test(
            format!(
                "{{7,1,1,{{0,{command_uuid}}},{{0,{{0,{{\"B\",1}},0}}}},1,1,{{0,{command_uuid}}},{group_uuid},1,1,1,{group_uuid},{{0,{command_uuid}}},0,1,1,{group_uuid},0}}"
            )
            .as_bytes(),
        );
    let command_refs = BTreeMap::from([(
        command_uuid.to_string(),
        "CommonCommand.OpenDashboard".to_string(),
    )]);

    let command_interface =
        parse_command_interface_blob(&body, &command_refs, &BTreeMap::new()).unwrap();
    let xml = format_command_interface_xml(&command_interface);

    assert!(xml.contains("<CommandsVisibility>"));
    assert!(xml.contains("<CommandsPlacement>"));
    assert!(xml.contains("<Placement>Manual</Placement>"));
    assert!(xml.contains("<CommandsOrder>"));
    assert!(xml.contains("<GroupsOrder>"));
    assert!(xml.contains("<Group>NavigationPanelImportant</Group>"));
    assert!(xml.find("<CommandsVisibility>").unwrap() < xml.find("<CommandsPlacement>").unwrap());
    assert!(xml.find("<CommandsPlacement>").unwrap() < xml.find("<CommandsOrder>").unwrap());
}

/// A command-visibility atom is adjustable: the common value is followed by a
/// counted list of per-role overrides, and the common value is a real `false`
/// even when an override next to it is `true`.
///
/// Provenance (`manifest.json` in the fixture directory): storage element
/// `86e05022-b8c0-4115-b7db-bc4853c53e50.1` of 1C:Trade Management
/// 11.5.27.75's `1cv8.cf`, packed body sha256
/// `54110a7878d50cca7c5decd9d2b11d6e6ef4e2628853e94763d190e7c0e271fd`; the
/// expectation is the platform's own
/// `Subsystems/CRMИМаркетинг/Ext/CommandInterface.xml` from an
/// `ibcmd config export` capture with 1C:Enterprise 8.3.27.2214, sha256
/// `acf24545f6aaf23e091aae4f563c19f979fd5f5f925e4ac6dca362494f8daadf`.
#[test]
fn platform_subsystem_command_interface_keeps_per_role_visibility() {
    let packed = decode_base64_mime(include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "command-interface-ut-role-visibility/raw-packed.bin.b64"
    )))
    .expect("platform-attested command interface payload");
    let native = decode_base64_mime(include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "command-interface-ut-role-visibility/native-command-interface.xml.b64"
    )))
    .expect("platform-attested command interface export");
    assert_eq!(
        format!("{:x}", Sha256::digest(&packed)),
        "54110a7878d50cca7c5decd9d2b11d6e6ef4e2628853e94763d190e7c0e271fd"
    );
    assert_eq!(
        format!("{:x}", Sha256::digest(&native)),
        "acf24545f6aaf23e091aae4f563c19f979fd5f5f925e4ac6dca362494f8daadf"
    );

    let command_refs = BTreeMap::from([
        (
            "4da477fc-4589-4f1c-b406-b657511d1b71".to_string(),
            "CommonCommand.ПанельОтчетовCRMИМаркетинг".to_string(),
        ),
        (
            "20797666-f9bb-4ac7-913d-3cd76bfdc5da".to_string(),
            "CommonCommand.ДополнительныеОтчетыCRMИМаркетинг".to_string(),
        ),
    ]);
    let metadata_refs = BTreeMap::from([
        (
            "9f082b87-a215-4bc7-9b04-a554322be6cd".to_string(),
            MetadataCommandReference {
                kind: "DocumentJournal".to_string(),
                name: "РеестрТорговыхДокументов".to_string(),
                use_standard_commands: true,
            },
        ),
        (
            "d131c610-218f-4a96-a660-8fcb7d3c347a".to_string(),
            MetadataCommandReference {
                kind: "Report".to_string(),
                name: "КонтактнаяИнформация".to_string(),
                use_standard_commands: true,
            },
        ),
        (
            "775035d0-dd99-4d68-83bb-d506d93fb18d".to_string(),
            MetadataCommandReference {
                kind: "Role".to_string(),
                name: "ОтчетыМаркетолога".to_string(),
                use_standard_commands: true,
            },
        ),
        (
            "39849230-e25f-45c6-8f91-42499144c1ed".to_string(),
            MetadataCommandReference {
                kind: "Role".to_string(),
                name: "ОтчетыРуководителяОтделаПродаж".to_string(),
                use_standard_commands: true,
            },
        ),
        (
            "fdb012c9-583a-42af-95da-070e75a58078".to_string(),
            MetadataCommandReference {
                kind: "Role".to_string(),
                name: "ПолныеПрава".to_string(),
                use_standard_commands: true,
            },
        ),
    ]);

    let command_interface = parse_command_interface_blob(&packed, &command_refs, &metadata_refs)
        .expect("platform-attested command interface body must decode");
    let xml = format_command_interface_xml(&command_interface);

    let native_xml = std::str::from_utf8(&native).expect("native command interface is UTF-8");
    const CLOSE: &str = "\t</CommandsVisibility>\r\n";
    let start = native_xml
        .find("\t<CommandsVisibility>\r\n")
        .expect("native CommandsVisibility section");
    let end = native_xml
        .find(CLOSE)
        .expect("native CommandsVisibility end")
        + CLOSE.len();
    assert!(xml.contains(&native_xml[start..end]), "{xml}");
}

/// `Catalog.ТабличныеЧастиБД` declares `UseStandardCommands=false`, so the
/// platform keeps its command-interface entries as the raw `0:<uuid>` sentinel
/// rather than resolving `Catalog.ТабличныеЧастиБД.StandardCommand.OpenList`
/// (a standard command that does not exist on this target), while a sibling
/// entry for `Catalog.ТипыБазДанных` (`UseStandardCommands=true`) resolves
/// normally. Before the `use_standard_commands` gate on `MetadataCommandReference`,
/// the reader resolved both alike -- wrong for the disabled one.
///
/// Provenance (`manifest.json` in the fixture directory): storage element
/// `27dc282e-77c4-462a-b827-a3616c7f11b4.1` of ERP UH 3.2.12.6's
/// `MDM_Management.cf`, packed body sha256
/// `a094aa5d41a51d21de0e729f7697de723c342fac493dfa9df2f1a80de2496c2f`; the
/// expectation is the platform's own
/// `Subsystems/ИнтеграцияСВнешнимиИсточникамиДанных/Subsystems/ВнешниеИнформационныеБазы/Ext/CommandInterface.xml`
/// from an `ibcmd config export` capture with 1C:Enterprise 8.3.27.2214, sha256
/// `7312e882df239654049d21ae922f9433bc5b9ab375105f905a877b0639613550`.
#[test]
fn platform_command_interface_declines_standard_command_when_use_standard_commands_false() {
    let packed = decode_base64_mime(include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "command-interface-mdm-use-standard-commands-false/raw-packed.bin.b64"
    )))
    .expect("platform-attested command interface payload");
    let native = decode_base64_mime(include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "command-interface-mdm-use-standard-commands-false/native-command-interface.xml.b64"
    )))
    .expect("platform-attested command interface export");
    assert_eq!(
        format!("{:x}", Sha256::digest(&packed)),
        "a094aa5d41a51d21de0e729f7697de723c342fac493dfa9df2f1a80de2496c2f"
    );
    assert_eq!(
        format!("{:x}", Sha256::digest(&native)),
        "7312e882df239654049d21ae922f9433bc5b9ab375105f905a877b0639613550"
    );

    let metadata_refs = BTreeMap::from([
        (
            "04c1ab92-f4fc-40e9-b0d6-a1c57a5a8b47".to_string(),
            MetadataCommandReference {
                kind: "Catalog".to_string(),
                name: "ТабличныеЧастиБД".to_string(),
                use_standard_commands: false,
            },
        ),
        (
            "858c9634-d409-4b3c-940a-1597db774e56".to_string(),
            MetadataCommandReference {
                kind: "Catalog".to_string(),
                name: "ТипыБазДанных".to_string(),
                use_standard_commands: true,
            },
        ),
        (
            "c92b8991-fc53-416b-8505-f0493559e7fd".to_string(),
            MetadataCommandReference {
                kind: "Catalog".to_string(),
                name: "ВнешниеИнформационныеБазы".to_string(),
                use_standard_commands: true,
            },
        ),
    ]);

    let command_interface = parse_command_interface_blob(&packed, &BTreeMap::new(), &metadata_refs)
        .expect("platform-attested command interface body must decode");
    let xml = format_command_interface_xml(&command_interface);

    let native_xml = std::str::from_utf8(&native).expect("native command interface is UTF-8");
    for (open, close) in [
        ("\t<CommandsVisibility>\r\n", "\t</CommandsVisibility>\r\n"),
        ("\t<CommandsOrder>\r\n", "\t</CommandsOrder>\r\n"),
    ] {
        let start = native_xml
            .find(open)
            .unwrap_or_else(|| panic!("native {open} section"));
        let end = native_xml
            .find(close)
            .unwrap_or_else(|| panic!("native {open} end"))
            + close.len();
        assert!(xml.contains(&native_xml[start..end]), "{xml}");
    }
    // The disabled catalog's own standard-command name never appears: every
    // occurrence of its uuid stayed the raw sentinel, in both sections.
    assert!(!xml.contains("ТабличныеЧастиБД.StandardCommand"));
    assert_eq!(
        xml.matches("0:04c1ab92-f4fc-40e9-b0d6-a1c57a5a8b47")
            .count(),
        2
    );
}

/// The `use_standard_commands` field the previous test's fixed `metadata_refs`
/// stood in for is itself read off the Catalog's own metadata row, not
/// invented: offset 31 of the owner-graph-normalized fields, the same slot
/// `parse_strict_catalog_properties_from_text` reads for the object's own
/// `<UseStandardCommands>`. Two real ERP UH MDM_Management catalogs, one of
/// each value, prove the extractor and the index built from it agree with
/// what each catalog's own XML says.
///
/// Provenance (`manifest.json` in the fixture directory): metadata-text CF
/// elements `04c1ab92-f4fc-40e9-b0d6-a1c57a5a8b47` (Catalog.ТабличныеЧастиБД)
/// and `858c9634-d409-4b3c-940a-1597db774e56` (Catalog.ТипыБазДанных) of
/// `MDM_Management.cf`.
#[test]
fn metadata_command_reference_index_reads_catalog_use_standard_commands_from_real_rows() {
    let false_packed = decode_base64_mime(include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "catalog-mdm-use-standard-commands/catalog-false-packed.bin.b64"
    )))
    .expect("platform-attested catalog payload");
    let true_packed = decode_base64_mime(include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "catalog-mdm-use-standard-commands/catalog-true-packed.bin.b64"
    )))
    .expect("platform-attested catalog payload");
    assert_eq!(
        format!("{:x}", Sha256::digest(&false_packed)),
        "1e435f2b6941e44316a166b27c5f36a19905de18623951f348aedf2eaf732ebf"
    );
    assert_eq!(
        format!("{:x}", Sha256::digest(&true_packed)),
        "774420280c788c0da678ba3918b64aca5d61619a1e248899dc688ef04d698f1f"
    );

    let false_uuid = "04c1ab92-f4fc-40e9-b0d6-a1c57a5a8b47";
    let true_uuid = "858c9634-d409-4b3c-940a-1597db774e56";
    let rows = vec![
        metadata_text_row_from_blob(false_uuid, &false_packed)
            .expect("Catalog.ТабличныеЧастиБД metadata row must decode"),
        metadata_text_row_from_blob(true_uuid, &true_packed)
            .expect("Catalog.ТипыБазДанных metadata row must decode"),
    ];
    assert_eq!(rows[0].kind.as_deref(), Some("Catalog"));
    assert_eq!(rows[1].kind.as_deref(), Some("Catalog"));

    let index = build_metadata_command_reference_index_from_texts(&rows);
    assert!(!index[false_uuid].use_standard_commands);
    assert!(index[true_uuid].use_standard_commands);
}

#[test]
fn extracts_standalone_content_used_items() {
    let first_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let second_uuid = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let body = deflate_for_test(format!("{{2,2,{first_uuid},{second_uuid},0}}").as_bytes());
    let references = StandaloneContentReferences {
        object_refs: BTreeMap::from([
            (first_uuid.to_string(), "Role.ReadOnlyUsers".to_string()),
            (
                second_uuid.to_string(),
                "CommonCommand.OpenAllReports".to_string(),
            ),
        ]),
    };

    let xml =
        String::from_utf8(extract_standalone_content_xml(&body, &references).unwrap()).unwrap();

    assert!(xml.starts_with("\u{feff}<?xml version=\"1.0\" encoding=\"UTF-8\"?>"));
    assert!(xml.contains("<StandaloneContent"));
    assert!(xml.contains("<Metadata>Role.ReadOnlyUsers</Metadata>"));
    assert!(xml.contains("<Metadata>CommonCommand.OpenAllReports</Metadata>"));
    assert!(
        xml.find("Role.ReadOnlyUsers").unwrap() < xml.find("CommonCommand.OpenAllReports").unwrap()
    );
}

#[test]
fn source_asset_only_dump_resolves_standalone_content_refs() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-standalone-content-source-only-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    fs::create_dir_all(&root).unwrap();
    let configuration_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let role_uuid = "0014cc2a-b5ed-427d-8ac6-116e92aaa9a4";
    let module = pack_module_blob_bytes(b"", None, None).unwrap().blob;
    let parent_configurations = deflate_for_test(b"{6,0}");
    let standalone = deflate_for_test(format!("{{2,1,{role_uuid},0}}").as_bytes());
    let role_metadata = deflate_for_test(
            format!(
                "{{1,\r\n{{6,\r\n{{3,\r\n{{1,0,{role_uuid}}},\"TargetMetrics\",{{1,\"en\",\"Target metrics\"}},\"\"}},0}}\r\n}}"
            )
            .as_bytes(),
        );
    let row = |file_name: String, data: Vec<u8>| ConfigRow {
        file_name,
        part_no: 0,
        data_size: data.len() as i64,
        binary_hex: encode_hex_for_test(&data),
    };
    let rows = vec![
        row(format!("{configuration_uuid}.0"), module.clone()),
        row(format!("{configuration_uuid}.5"), module.clone()),
        row(format!("{configuration_uuid}.6"), module.clone()),
        row(format!("{configuration_uuid}.7"), module),
        row(format!("{configuration_uuid}.4"), parent_configurations),
        row(format!("{configuration_uuid}.f"), standalone),
        row(role_uuid.to_string(), role_metadata),
    ];

    let dumped = dump_table_rows(&root, "Config", rows, false, false, false).unwrap();

    assert_eq!(dumped.metadata_xml_rows, 0);
    assert_eq!(dumped.source_asset_rows, 2);
    let xml = fs::read_to_string(root.join("Ext/StandaloneConfigurationContent.bin")).unwrap();
    assert!(xml.contains("<Metadata>Role.TargetMetrics</Metadata>"));
    assert!(!xml.contains(role_uuid));
    assert!(!root.join("ConfigDumpInfo.xml").exists());

    let _ = fs::remove_dir_all(root);
}

