#[test]
fn extracts_form_search_addition_type_from_layout_code() {
    let mut items = Vec::new();
    let table_name_by_id = BTreeMap::from([("25".to_string(), "Rows".to_string())]);
    for (code, expected_tag, expected_type) in [
        ("0", "SearchStringAddition", "SearchStringRepresentation"),
        ("1", "ViewStatusAddition", "ViewStatusRepresentation"),
        ("2", "SearchControlAddition", "SearchControl"),
    ] {
        let item = parse_form_child_item(
                &format!(
                    r#"{{6,{{44,02023637-7868-4a5f-8576-835a76e0c9ba}},0,0,0,{code},"SearchAddition",{{1,0}},{{1,0}},1,1,0,1,{{1,0}},0,0,0,0,0,{{25,{code}}}}}"#
                ),
                None,
                None,
                &table_name_by_id,
                &BTreeMap::new(),
                &[],
                &BTreeMap::new(),
            )
            .unwrap();

        assert_eq!(item.tag, expected_tag);
        assert_eq!(item.item_type, Some(expected_type));
        assert_eq!(item.addition_source_item.as_deref(), Some("Rows"));
        items.push(item);
    }

    let xml = format_form_child_items_xml(&items, 1);

    assert!(xml.contains("<SearchStringAddition"));
    assert_eq!(xml.matches("<Item>Rows</Item>").count(), 3);
    assert!(xml.contains("<Type>SearchStringRepresentation</Type>"));
    assert!(xml.contains("<ViewStatusAddition"));
    assert!(xml.contains("<Type>ViewStatusRepresentation</Type>"));
    assert!(xml.contains("<SearchControlAddition"));
    assert!(xml.contains("<Type>SearchControl</Type>"));
}

#[test]
fn extracts_table_service_child_items_from_layout_fields() {
    let form_uuid = "02023637-7868-4a5f-8576-835a76e0c9ba";
    let command_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let commands = vec![FormCommand {
        use_rights: None,
        id: "15".to_string(),
        reference_uuid: command_uuid.to_string(),
        name: "Run".to_string(),
        title: Vec::new(),
        tooltip: Vec::new(),
        picture_ref: None,
        picture_load_transparent: false,
        picture_transparent_pixel: None,
        shortcut: None,
        action: String::new(),
        representation: None,
        functional_options: Vec::new(),
        modifies_saved_data: None,
        current_row_use: None,
    }];
    let table_name_by_id = BTreeMap::from([("25".to_string(), "Rows".to_string())]);
    // `parse_form_child_item_extended_tooltip` (`src/mssql_dump/form_body.rs`)
    // requires the nested `{12,...}` tooltip's own name to satisfy
    // `is_form_extended_tooltip_name` — it must literally contain
    // "ExtendedTooltip"/"РасширеннаяПодсказка" (optionally followed only by
    // digits), matching the naming convention used by every other extended
    // tooltip fixture in this suite. The stale "RowsSearchTip" name never
    // matched that convention, so `extended_tooltip` was always `None`.
    //
    // The nested `RowsSearchContext` `ContextMenu` also predates
    // `format_form_context_menu_xml`'s open-vs-self-closing rule (open only
    // when `autofill == Some(false)` or it has its own children); its
    // 8-field blob was too short for `parse_form_context_menu_autofill` to
    // read slot 20 at all. Extended it to the real 29-field ContextMenu
    // shape (see `extracts_field_context_menu_as_direct_child`) with slot 20
    // set to `{1,0}` for `Autofill=false`.
    let item = parse_form_child_item(
            &format!(
                r#"{{73,{{25,{form_uuid}}},0,1,0,"Rows",0,0,0,{{1,0}},0,1,{{22,{{26,{form_uuid}}},0,0,0,8,"RowsContext",{{1,0}},{{1,0}},0,1,0}},1,{{22,{{27,{form_uuid}}},0,0,0,9,"RowsBar",{{1,0}},{{1,0}},0,1,0,0,0,2,2,{{4,4,{{0}},4}},{{8,3,0,1,100}},{{0,0,0}},1,{{1,0,1,0}},1,bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb,{{34,{{28,{form_uuid}}},0,0,0,"RowsButton",{{1,0}},1,{{15,{command_uuid}}},{{0}},0,1,0,0,2,2,0,0,0,{{12,{{31,{form_uuid}}},0,0,0,0,"RowsButtonTip",{{1,0}},{{1,0}},1,0,0,2,2}}}}}},1,{{6,{{29,{form_uuid}}},0,0,0,0,"RowsSearch",{{1,0}},{{1,0}},1,1,0,1,{{1,0}},0,1,{{22,{{30,{form_uuid}}},0,0,0,8,"RowsSearchContext",{{1,0}},{{1,0}},0,1,0,0,0,2,2,{{3,4,{{0}}}},{{7,3,0,1,100}},{{0,0,0}},1,{{1,0}},0,1,0,0,0,3,3,0}},0,0,{{25,0}},{{12,{{32,{form_uuid}}},0,0,0,0,"RowsSearchExtendedTooltip",{{1,0}},{{1,0}},1,0,0,2,2}}}}}}"#
            ),
            Some("RowsData"),
            None,
            &table_name_by_id,
            &BTreeMap::new(),
            &commands,
            &BTreeMap::new(),
        )
        .unwrap();

    assert_eq!(item.tag, "Table");
    assert_eq!(
        item.child_items
            .iter()
            .map(|child| child.tag)
            .collect::<Vec<_>>(),
        vec!["ContextMenu", "AutoCommandBar", "SearchStringAddition"]
    );
    assert_eq!(item.child_items[1].child_items[0].tag, "Button");
    assert!(!item.child_items[1].auto_command_bar_empty_element);
    assert_eq!(
        item.child_items[1].child_items[0].command_name.as_deref(),
        Some("Form.Command.Run")
    );
    assert_eq!(item.child_items[2].child_items[0].tag, "ContextMenu");
    assert_eq!(
        item.child_items[2]
            .extended_tooltip
            .as_ref()
            .map(|tooltip| (tooltip.name.as_str(), tooltip.id.as_str())),
        Some(("RowsSearchExtendedTooltip", "32"))
    );

    let xml = format_form_child_items_xml(&[item], 1);

    let context_at = xml.find("\t\t<ContextMenu").unwrap();
    let bar_at = xml.find("\t\t<AutoCommandBar").unwrap();
    let addition_at = xml.find("\t\t<SearchStringAddition").unwrap();
    assert!(context_at < bar_at);
    assert!(bar_at < addition_at);
    assert!(xml.contains(r#"<Button name="RowsButton" id="28">"#));
    assert!(xml.contains(r#"<ContextMenu name="RowsSearchContext" id="30">"#));
    assert!(!xml.contains("\t\t<ChildItems>\r\n\t\t\t<SearchStringAddition"));
}

