#[test]
fn omits_popup_item_source_without_an_exact_owner_or_type() {
    let unknown_owner = format!(r#"{{7,{{0}},{{68,{FORM_ITEM_TYPE_UUID}}},2,1,0,0,{{0}},{{0}}}}"#);
    let wrong_type = r#"{7,{0},{68,aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa},2,1,0,0,{0},{0}}"#;
    let nonzero_global =
        format!(r#"{{7,{{0}},{{68,{FORM_GLOBAL_COMMAND_SOURCE_TYPE_UUID}}},2,1,0,0,{{0}},{{0}}}}"#);

    for source in [&unknown_owner, wrong_type, &nonzero_global] {
        let mut fields = vec!["0"; 21];
        fields[20] = source;
        assert_eq!(
            parse_form_popup_command_source_with_items(&fields, &BTreeMap::new()),
            None,
            "unexpected Popup source for {source}"
        );
    }
}

#[test]
fn requires_exact_popup_command_source_shape_and_sentinels() {
    let cases = [
        format!(r#"{{7,{{0}},{{1,{FORM_ITEM_TYPE_UUID}}},2,3,0,0,{{0}},{{0}},1}}"#),
        format!(r#"{{7,{{0}},{{1,{FORM_ITEM_TYPE_UUID},0}},2,3,0,0,{{0}},{{0}}}}"#),
        format!(r#"{{6,{{0}},{{1,{FORM_ITEM_TYPE_UUID}}},2,3,0,0,{{0}},{{0}}}}"#),
        format!(r#"{{7,{{0}},{{1,{FORM_ITEM_TYPE_UUID}}},1,3,0,0,{{0}},{{0}}}}"#),
        format!(r#"{{7,{{0}},{{1,{FORM_ITEM_TYPE_UUID}}},2,3,1,0,{{0}},{{0}}}}"#),
        format!(r#"{{7,{{0}},{{1,{FORM_ITEM_TYPE_UUID}}},2,3,0,1,{{0}},{{0}}}}"#),
    ];
    let owners = BTreeMap::from([("1".to_string(), "RenamedOwner".to_string())]);

    for source in &cases {
        let mut fields = vec!["0"; 21];
        fields[20] = source;
        assert_eq!(
            parse_form_popup_command_source_with_items(&fields, &owners),
            None,
            "unexpected Popup source for {source}"
        );
    }
}

#[test]
fn recognizes_form_item_picture_asset_formats() {
    assert!(is_form_item_picture_content(b"\x89PNG\r\n\x1a\npayload"));
    assert!(is_form_item_picture_content(b"GIF87apayload"));
    assert!(is_form_item_picture_content(b"\x00\x00\x01\x00payload"));
    assert!(is_form_item_picture_content(b"\xff\xd8\xff\xe0payload"));
    assert!(is_form_item_picture_content(b"BMpayload"));
    assert!(is_form_item_picture_content(b"PK\x03\x04payload"));
    assert!(is_form_item_picture_content(b"<svg/>"));
    assert!(is_form_item_picture_content(
        b"<?xml version=\"1.0\"?><svg/>"
    ));
    assert!(!is_form_item_picture_content(b"plain text"));
}

#[test]
fn extracts_chart_of_characteristic_types_xml_from_metadata_blob() {
    let uuid = "d003f1f8-d632-4f80-adad-af1583998864";
    let text = include_str!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/chart-of-characteristic-types/raw/d003f1f8-d632-4f80-adad-af1583998864.txt"
    );
    let row = metadata_text_row_from_text(uuid, text.trim_start_matches('\u{feff}').to_string())
        .expect("native CCT row");
    let rows = std::slice::from_ref(&row);
    let type_index = build_metadata_type_index_from_texts(rows);
    let object_refs = build_metadata_object_reference_index_from_texts(rows);
    let fields = metadata_object_fields(&row.text).expect("native CCT fields");
    let header = row.header.as_ref().expect("native CCT header");
    assert_eq!(fields.len(), 59);
    assert_eq!(metadata_header_field_index(&fields, uuid), Some(13));
    assert_eq!(fields[51].trim(), "1");
    assert_eq!(type_index.len(), 6);
    for (slot, generated_type) in [
        (1, "ChartOfCharacteristicTypesObject"),
        (3, "ChartOfCharacteristicTypesRef"),
        (5, "ChartOfCharacteristicTypesSelection"),
        (7, "ChartOfCharacteristicTypesList"),
        (9, "Characteristic"),
        (11, "ChartOfCharacteristicTypesManager"),
    ] {
        assert_eq!(
            type_index.get(fields[slot].trim()).map(String::as_str),
            Some(format!("cfg:{generated_type}.{}", header.name).as_str())
        );
    }
    let malformed_generated_type = row.text.replacen(fields[12].trim(), "not-a-uuid", 1);
    let malformed_generated_type_row =
        metadata_text_row_from_text(uuid, malformed_generated_type).expect("malformed CCT row");
    assert!(
        build_metadata_type_index_from_texts(std::slice::from_ref(&malformed_generated_type_row))
            .is_empty(),
        "CCT generated-type vector must fail atomically"
    );
    let mut characteristics_diagnostic = None;
    assert!(
        decode_owner_characteristics(
            owner_graph::CharacteristicsOwnerFamily::ChartOfCharacteristicTypes,
            &fields,
            &type_index,
            &object_refs,
            &object_refs,
            &mut characteristics_diagnostic,
        )
        .is_some(),
        "characteristics: {characteristics_diagnostic:?}"
    );
    assert!(
        parse_metadata_type_pattern(fields[18], &type_index).is_some(),
        "value types"
    );
    let standard_outer = split_information_register_braced_fields(fields[38]).unwrap();
    let standard_payload = split_information_register_braced_fields(standard_outer[1]).unwrap();
    for ((marker, name), triplet) in CCT_STANDARD_ATTRIBUTES
        .iter()
        .copied()
        .zip(standard_payload[2..].chunks_exact(3))
    {
        let bag = parse_information_register_standard_attribute_bag(triplet[2])
            .unwrap_or_else(|| panic!("{name}: bag"));
        assert!(bag.has_type_reduction_mode, "{name}: reduction mode");
        let fill = bag
            .get(INFORMATION_REGISTER_STANDARD_ATTRIBUTE_FILL_VALUE_PROPERTY_UUID)
            .unwrap_or_else(|| panic!("{name}: fill property"));
        assert!(
            parse_cct_standard_attribute_fill_value(
                fill,
                marker,
                &header.name,
                &type_index,
                &object_refs,
            )
            .is_some(),
            "{name}: fill value {fill}"
        );
    }
    let mut legacy_standard_payload = standard_payload
        .iter()
        .map(|field| (*field).to_string())
        .collect::<Vec<_>>();
    let mut legacy_first_bag =
        split_information_register_braced_fields(&legacy_standard_payload[4])
            .unwrap()
            .iter()
            .map(|field| (*field).to_string())
            .collect::<Vec<_>>();
    legacy_first_bag.drain(12..14);
    legacy_first_bag[0] = "13".to_string();
    legacy_first_bag[1] = "24".to_string();
    legacy_standard_payload[4] = format!("{{{}}}", legacy_first_bag.join(","));
    let legacy_standard_attributes = format!("{{1,{{{}}}}}", legacy_standard_payload.join(","));
    assert!(
        parse_cct_standard_attributes(
            &legacy_standard_attributes,
            &header.name,
            &type_index,
            &object_refs,
        )
        .is_none(),
        "legacy CCT standard-attribute bag must remain closed"
    );
    assert!(
        parse_cct_standard_attributes(fields[38], &header.name, &type_index, &object_refs)
            .is_some(),
        "standard attributes"
    );
    assert!(
        parse_cct_input_by_string(fields[33], &header.name).is_some(),
        "input by string"
    );
    let extracted = extract_metadata_source_xml_from_text_row_audited(
        &row,
        &type_index,
        &BTreeSet::new(),
        &object_refs,
        &object_refs,
        &object_refs,
        &BTreeMap::new(),
        &CalculationRootRecalculationReferences::default(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        InfobaseConfigSourceVersion::V2_20,
    )
    .expect("native CCT source XML");
    assert_eq!(
        extracted.relative_path,
        PathBuf::from("ChartsOfCharacteristicTypes/CorpusCharacteristics.xml")
    );
    let expected = include_bytes!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/chart-of-characteristic-types/native/ChartsOfCharacteristicTypes/CorpusCharacteristics.xml"
    );
    assert_eq!(extracted.xml, expected);
}

#[test]
fn accepts_only_evidenced_cct_attribute_and_tabular_wrappers() {
    let zero = "00000000-0000-0000-0000-000000000000";
    assert!(cct_attribute_wrapper_is_exact(
        &["2", "payload", "0", "0", "1", "1"],
        false
    ));
    assert!(cct_attribute_wrapper_is_exact(
        &[
            "3",
            "payload",
            "0",
            "2",
            "1",
            "0",
            "0",
            &format!("{{1,{zero}}}")
        ],
        false
    ));
    assert!(cct_attribute_wrapper_is_exact(
        &["8", "payload", "0", "1", "1"],
        true
    ));
    assert!(!cct_attribute_wrapper_is_exact(
        &[
            "3",
            "payload",
            "0",
            "2",
            "1",
            "0",
            "1",
            &format!("{{1,{zero}}}")
        ],
        false
    ));
    assert!(!cct_attribute_wrapper_is_exact(
        &["3", "payload", "0", "2", "1", "0", "0", "{1,not-a-uuid}"],
        false
    ));
    assert!(!cct_attribute_wrapper_is_exact(
        &["8", "payload", "0", "1"],
        true
    ));

    let cct_section = |wrapper: &[&str]| {
        parse_tabular_section_envelope("ChartOfCharacteristicTypes", wrapper).is_some()
    };
    assert!(cct_section(&["0", "payload", "0"]));
    assert!(cct_section(&["1", "payload", "0", "5"]));
    // The trailing slot is the section's stored LineNumberLength: one CCT
    // section of UT 11.5.27.75 writes 9 and its native XML says 9, so the
    // envelope grammar reads the slot instead of pinning it to 5.
    assert!(cct_section(&["1", "payload", "0", "9"]));
    assert!(!cct_section(&["1", "payload", "0"]));
    assert!(!cct_section(&["2", "payload", "0", "5"]));
}

#[test]
fn extracts_common_command_xml_from_metadata_blob() {
    let uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let blob = deflate_for_test(
            format!(
                "{{1,\r\n{{2,\r\n{{1,\r\n{{2,{uuid},078a6af8-d22c-4248-9c33-7e90075a3d2c}},\r\n{{9,\r\n{{4,0,{{0}},\"\",-1,-1,1,0,\"\"}},3,\r\n{{1,\"en\",\"Open settings\"}},1,\r\n{{0,0,0}},0,\r\n{{1,aabb34e1-98c1-4bd0-bf7f-243f95437b44}},\r\n{{\"Pattern\"}},\r\n{{3,\r\n{{1,0,{uuid}}},\"OpenSettings\",{{1,\"en\",\"Open settings\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},0,0,0}}\r\n}}\r\n}},0}}"
            )
            .as_bytes(),
        );

    let extracted = extract_metadata_source_xml(
        &blob,
        uuid,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
    )
    .unwrap();
    let properties = parse_simple_metadata_xml_properties(&extracted.xml).unwrap();

    assert_eq!(
        extracted.relative_path,
        PathBuf::from("CommonCommands").join("OpenSettings.xml")
    );
    assert_eq!(properties.kind, "CommonCommand");
    assert_eq!(properties.uuid, uuid);
    assert_eq!(properties.name, "OpenSettings");
    let xml = String::from_utf8(extracted.xml).unwrap();
    assert!(xml.contains("<Group>ActionsPanelTools</Group>"), "{}", xml);
    assert!(
        xml.contains("<Representation>Auto</Representation>"),
        "{}",
        xml
    );
    assert!(
        xml.contains("<IncludeHelpInContents>false</IncludeHelpInContents>"),
        "{}",
        xml
    );
    assert!(
        xml.contains("<ParameterUseMode>Single</ParameterUseMode>"),
        "{}",
        xml
    );
    assert!(
        xml.contains("<ModifiesData>false</ModifiesData>"),
        "{}",
        xml
    );
    assert!(
        xml.contains("<OnMainServerUnavalableBehavior>Auto</OnMainServerUnavalableBehavior>"),
        "{}",
        xml
    );
}

#[test]
fn parses_common_command_parameter_type_pattern() {
    let catalog_type_uuid = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let defined_type_uuid = "cccccccc-cccc-4ccc-cccc-cccccccccccc";
    let type_index = BTreeMap::from([
        (
            catalog_type_uuid.to_string(),
            "cfg:CatalogRef.Products".to_string(),
        ),
        (
            defined_type_uuid.to_string(),
            "cfg:DefinedType.TradeOffer".to_string(),
        ),
    ]);

    let types = parse_common_command_parameter_types(
        &format!(
            r##"{{"Pattern",{{"#",{catalog_type_uuid}}},{{"#",{defined_type_uuid}}},{{"S",25,0}}}}"##
        ),
        &type_index,
    );

    assert_eq!(
        types.iter().map(metadata_type_xml_name).collect::<Vec<_>>(),
        [
            "cfg:CatalogRef.Products",
            "cfg:DefinedType.TradeOffer",
            "xs:string",
        ]
    );
    assert!(matches!(
        types.get(1),
        Some(ConstantValueType::ReferenceTypeSet { reference })
            if reference == "cfg:DefinedType.TradeOffer"
    ));

    let mut xml = String::new();
    format_common_command_parameter_type_xml(&mut xml, &types);
    assert!(xml.contains("<v8:Type>cfg:CatalogRef.Products</v8:Type>"));
    assert!(xml.contains("<v8:TypeSet>cfg:DefinedType.TradeOffer</v8:TypeSet>"));
    assert!(xml.contains("<v8:Type>xs:string</v8:Type>"));
}

/// Every pattern below is a byte layout the platform actually wrote into
/// 1C:Trade Management 11.5.27.75 - `{"L"}` sits beside `{"S"}`, `{"B"}`,
/// `{"N",…}` and `{"#",<ValueListType>}`, and it also occurs alone. It keeps its
/// pattern position in the emitted `<Type>` block, and it no longer takes its
/// siblings down with it.
#[test]
fn parses_the_null_type_pattern_element_without_discarding_its_siblings() {
    let value_list_uuid = "4772b3b4-f4a3-49c0-a1a5-8cb5961511a3";

    for (pattern, expected) in [
        (r#"{"Pattern",{"S"},{"L"}}"#, vec!["xs:string", "v8:Null"]),
        (r#"{"Pattern",{"B"},{"L"}}"#, vec!["xs:boolean", "v8:Null"]),
        (
            r#"{"Pattern",{"L"},{"N",10,0,1}}"#,
            vec!["v8:Null", "xs:decimal"],
        ),
        (r#"{"Pattern",{"L"}}"#, vec!["v8:Null"]),
        (
            &format!(r##"{{"Pattern",{{"#",{value_list_uuid}}},{{"L"}}}}"##),
            vec!["v8:ValueListType", "v8:Null"],
        ),
    ] {
        let value_types = parse_form_metadata_type_pattern(pattern, &BTreeMap::new())
            .unwrap_or_else(|| panic!("pattern {pattern} must parse"));
        assert_eq!(
            value_types
                .iter()
                .map(metadata_type_xml_name)
                .collect::<Vec<_>>(),
            expected,
            "{pattern}"
        );
        assert_eq!(
            parse_metadata_type_pattern(pattern, &BTreeMap::new())
                .unwrap_or_else(|| panic!("pattern {pattern} must parse"))
                .iter()
                .map(metadata_type_xml_name)
                .collect::<Vec<_>>(),
            expected,
            "{pattern}"
        );
    }

    // `v8:Null` is an ordinary `<v8:Type>` leaf, and the qualifiers of the
    // sibling it travels with are still written after it.
    let xml = format_form_metadata_types_xml(
        &parse_form_metadata_type_pattern(r#"{"Pattern",{"S"},{"L"}}"#, &BTreeMap::new()).unwrap(),
    );
    assert!(xml.contains("<v8:Type>xs:string</v8:Type>"), "{xml}");
    assert!(xml.contains("<v8:Type>v8:Null</v8:Type>"), "{xml}");
    assert!(
        xml.contains("<v8:AllowedLength>Variable</v8:AllowedLength>"),
        "{xml}"
    );
}

/// Every one of these identifiers is a platform type serialized by a Form
/// attribute pattern of 1C:Trade Management 11.5.27.75, with the namespace the
/// platform declares inline on the emitted element.
#[test]
fn resolves_the_platform_type_identifiers_serialized_by_form_patterns() {
    for (pattern, expected_xml) in [
        (
            r##"{"Pattern",{"#",48510817-200c-48c2-9973-06cf90840514}}"##,
            "<v8:Type xmlns:pdfdoc=\"http://v8.1c.ru/8.3/data/pdf\">pdfdoc:PDFDocument</v8:Type>",
        ),
        (
            r##"{"Pattern",{"#",95de81b0-81c3-4936-9dbb-6400e5c90378}}"##,
            "<v8:Type xmlns:d5p1=\"http://v8.1c.ru/8.2/data/geo\">d5p1:GeographicalSchema</v8:Type>",
        ),
        (
            r##"{"Pattern",{"#",0387f3a2-7df5-4804-948b-4580a51e4a15}}"##,
            "<v8:Type>v8:StandardBeginningDate</v8:Type>",
        ),
        (
            r##"{"Pattern",{"#",474c3bf6-08b5-4ddc-a2ad-989cedf11583}}"##,
            "<v8:TypeSet>cfg:EnumRef</v8:TypeSet>",
        ),
    ] {
        let value_types = normalize_form_type_pattern(
            parse_form_metadata_type_pattern(pattern, &BTreeMap::new())
                .unwrap_or_else(|| panic!("pattern {pattern} must parse")),
        );
        let xml = format_form_metadata_types_xml(&value_types);
        assert!(xml.contains(expected_xml), "{pattern}: {xml}");
    }

    // Both tables now name the enumeration family. They did not before: the
    // reference-family table was missing the row, so a data-composition
    // `valueType` naming it failed closed on an identifier the other table had
    // carried all along, which cost one template its whole export.
    assert_eq!(
        builtin_type_reference("474c3bf6-08b5-4ddc-a2ad-989cedf11583"),
        Some("cfg:EnumRef")
    );
    assert_eq!(
        information_register_builtin_reference("474c3bf6-08b5-4ddc-a2ad-989cedf11583"),
        Some("cfg:EnumRef")
    );
    assert_eq!(
        parse_information_register_type_pattern(
            r##"{"Pattern",{"#",474c3bf6-08b5-4ddc-a2ad-989cedf11583}}"##,
            &BTreeMap::new(),
        )
        .as_deref(),
        Some(
            [ConstantValueType::ReferenceTypeSet {
                reference: "cfg:EnumRef".to_string(),
            }]
            .as_slice()
        )
    );
}

/// `Documents/ПоручениеЭкспедитору` writes `{"Pattern",{"#",<DocumentRef>},
/// {"S",500,1}}` for its `Основание` attribute and
/// `Documents/ТранспортныйКонтейнерЭДО` writes
/// `{"Pattern",{"#",<DocumentRef>},{"#",<CatalogRef.…>}}` for `ОбъектВладелец`.
/// Both are the platform's own bytes, and in both the platform's XML puts the
/// ordinary type before the type set - the same layout every Catalog,
/// BusinessProcess and DataProcessor attribute already used.
#[test]
fn a_document_attribute_orders_its_type_sets_last_like_every_other_root_object() {
    let catalog_type_uuid = "c000410b-b593-4ef1-8c9c-d464abe8dd86";
    let type_index = BTreeMap::from([(
        catalog_type_uuid.to_string(),
        "cfg:CatalogRef.УдалитьСоглашенияОбИспользованииЭД".to_string(),
    )]);

    for (pattern, expected) in [
        (
            r##"{"Pattern",{"#",38bfd075-3e63-4aaa-a93e-94521380d579},{"S",500,1}}"##,
            vec!["xs:string", "cfg:DocumentRef"],
        ),
        (
            &format!(
                r##"{{"Pattern",{{"#",38bfd075-3e63-4aaa-a93e-94521380d579}},{{"#",{catalog_type_uuid}}}}}"##
            ),
            vec![
                "cfg:CatalogRef.УдалитьСоглашенияОбИспользованииЭД",
                "cfg:DocumentRef",
            ],
        ),
    ] {
        let value_types = stable_partition_metadata_types(classify_metadata_reference_type_sets(
            parse_metadata_type_pattern(pattern, &type_index)
                .unwrap_or_else(|| panic!("pattern {pattern} must parse")),
        ));
        assert_eq!(
            value_types
                .iter()
                .map(metadata_type_xml_name)
                .collect::<Vec<_>>(),
            expected,
            "{pattern}"
        );
        let xml = format_metadata_types_xml_with_indent(&value_types, "\t");
        let type_set_at = xml
            .find("<v8:TypeSet>cfg:DocumentRef</v8:TypeSet>")
            .unwrap();
        let last_type_at = xml.rfind("<v8:Type>").unwrap();
        assert!(last_type_at < type_set_at, "{pattern}: {xml}");
    }
}

