#[test]
fn parses_common_command_input_field_pictures_and_shortcut() {
    let (select_reference, select_load_transparent) =
        parse_common_command_picture_value(r#"{4,1,{-1},"",-1,-1,1,0,""}"#, &BTreeMap::new())
            .unwrap();
    let (reference, load_transparent) =
        parse_common_command_picture_value(r#"{4,1,{-7},"",-1,-1,1,0,""}"#, &BTreeMap::new())
            .unwrap();

    assert_eq!(
        select_reference,
        Some("StdPicture.InputFieldSelect".to_string())
    );
    assert!(select_load_transparent);
    assert_eq!(reference, Some("StdPicture.InputFieldOpen".to_string()));
    assert!(load_transparent);
    assert_eq!(
        parse_common_command_shortcut_value("{0,120,0}"),
        Some("F9".to_string())
    );
    assert_eq!(parse_common_command_shortcut_value("{0,0,0}"), None);
}

/// Renders a Windows-spelled shortcut the way this host's export will write
/// it, so assertions on emitted XML stay correct on either host.
fn host_shortcut(windows_spelling: &str) -> String {
    windows_spelling
        .replace("Ctrl", ShortcutModifierStyle::host().ctrl())
        .replace("Alt", ShortcutModifierStyle::host().alt())
}

#[test]
fn parses_common_command_shortcut_key_and_modifier_matrix_strictly() {
    // The bitmask is host-neutral; only the CTRL and ALT bits' spelling
    // depends on the host the export runs on. Both spellings are pinned here
    // so neither can drift with whichever machine runs the suite.
    for (raw, expected) in [
        ("{0,8,0}", "BackSpace"),
        ("{0,13,8}", "Ctrl+Enter"),
        ("{0,49,8}", "Ctrl+1"),
        ("{0,65,0}", "A"),
        ("{0,90,0}", "Z"),
        ("{0,96,0}", "Num 0"),
        ("{0,105,16}", "Alt+Num 9"),
        ("{0,110,0}", "Num ."),
        ("{0,111,0}", "Num /"),
        ("{0,112,0}", "F1"),
        ("{0,123,0}", "F12"),
        ("{0,83,4}", "Shift+S"),
        ("{0,83,8}", "Ctrl+S"),
        ("{0,83,16}", "Alt+S"),
        ("{0,83,12}", "Ctrl+Shift+S"),
        ("{0,70,24}", "Ctrl+Alt+F"),
        ("{0,70,28}", "Ctrl+Alt+Shift+F"),
    ] {
        assert_eq!(
            parse_common_command_shortcut_value_with_style(raw, ShortcutModifierStyle::Windows)
                .as_deref(),
            Some(expected),
            "{raw}"
        );
    }

    for (raw, expected) in [
        ("{0,8,0}", "BackSpace"),
        ("{0,13,8}", "Cmd+Enter"),
        ("{0,49,8}", "Cmd+1"),
        ("{0,105,16}", "Option+Num 9"),
        // Real bytes: `ssl`-demo's `DataProcessors/КонсольЗапросов/Forms/
        // Форма` carries key_code 111 (`VK_DIVIDE`) twice, modifier 8 and 12,
        // native `Cmd+Num /` and `Cmd+Shift+Num /`.
        ("{0,111,8}", "Cmd+Num /"),
        ("{0,111,12}", "Cmd+Shift+Num /"),
        ("{0,112,0}", "F1"),
        ("{0,83,4}", "Shift+S"),
        ("{0,83,8}", "Cmd+S"),
        ("{0,83,16}", "Option+S"),
        ("{0,83,12}", "Cmd+Shift+S"),
        ("{0,70,24}", "Cmd+Option+F"),
        ("{0,70,28}", "Cmd+Option+Shift+F"),
    ] {
        assert_eq!(
            parse_common_command_shortcut_value_with_style(raw, ShortcutModifierStyle::Macos)
                .as_deref(),
            Some(expected),
            "{raw}"
        );
    }

    for raw in [
        "{0,0,0}",
        "{0,0,8}",
        "{0,64,0}",
        "{0,47,0}",
        "{0,58,0}",
        "{0,91,0}",
        "{0,95,0}",
        "{0,106,0}",
        "{0,109,0}",
        "{0,124,0}",
        "{0,70,1}",
        "{0,70,32}",
        "{1,70,24}",
        "{0,70}",
        "{0,70,24,0}",
    ] {
        assert_eq!(parse_common_command_shortcut_value(raw), None, "{raw}");
    }
}

