#[test]
fn writes_help_xml_and_html_to_source_layout() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-mssql-dump-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    fs::create_dir_all(&root).unwrap();
    let uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let metadata = deflate_for_test(
        catalog_metadata_text_for_test("57", uuid, "Products", &[], &[]).as_bytes(),
    );
    let help = deflate_for_test(
        b"{5,1,\"ru\",{#base64:PGh0bWw+PC9odG1sPg==},1,\"shot.png\",1,{#base64:iVBORw0KGgo=}}",
    );
    let rows = vec![
        ConfigRow {
            file_name: uuid.to_string(),
            part_no: 0,
            data_size: metadata.len() as i64,
            binary_hex: encode_hex_for_test(&metadata),
        },
        ConfigRow {
            file_name: format!("{uuid}.5"),
            part_no: 0,
            data_size: help.len() as i64,
            binary_hex: encode_hex_for_test(&help),
        },
    ];

    let dumped = dump_table_rows_with_source_version(
        &root,
        "Config",
        rows,
        false,
        false,
        true,
        InfobaseConfigSourceVersion::V2_21,
    )
    .unwrap();

    assert_eq!(dumped.metadata_xml_rows, 1);
    assert_eq!(dumped.source_asset_rows, 1);
    let help_xml = fs::read(root.join("Catalogs/Products/Ext/Help.xml")).unwrap();
    assert!(help_xml.starts_with(b"\xEF\xBB\xBF<?xml"));
    assert!(help_xml.ends_with(b"</Help>"));
    assert!(!help_xml.ends_with(b"</Help>\r\n"));
    let help_xml_text = String::from_utf8(help_xml).unwrap();
    assert!(help_xml_text.contains(r#"version="2.21""#));
    assert!(help_xml_text.contains("<Page>ru</Page>"));
    assert_eq!(
        fs::read(root.join("Catalogs/Products/Ext/Help/ru.html")).unwrap(),
        b"<html></html>"
    );
    assert_eq!(
        fs::read(root.join("Catalogs/Products/Ext/Help/_files/shot.png")).unwrap(),
        b"\x89PNG\r\n\x1a\n"
    );
    let help_row = dumped
        .rows
        .iter()
        .find(|row| row.file_name == format!("{uuid}.5"))
        .unwrap();
    assert_eq!(
        help_row.source_asset_path.as_deref(),
        Some("Catalogs/Products/Ext/Help.xml")
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn prefers_new_object_help_suffix_when_legacy_help_blob_remains() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-mssql-dump-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    fs::create_dir_all(&root).unwrap();
    let uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let metadata = deflate_for_test(
            format!(
                "{{1,\r\n{{57,\r\n{{0,\r\n{{3,\r\n{{1,0,{uuid}}},\"Products\",{{1,\"en\",\"Products\"}},\"\"}}\r\n}}\r\n}}\r\n}}"
            )
            .as_bytes(),
        );
    let legacy_help = deflate_for_test(b"{5,1,\"ru\",{#base64:b2xk}}");
    let current_help = deflate_for_test(b"{5,1,\"ru\",{#base64:bmV3}}");
    let rows = vec![
        ConfigRow {
            file_name: uuid.to_string(),
            part_no: 0,
            data_size: metadata.len() as i64,
            binary_hex: encode_hex_for_test(&metadata),
        },
        ConfigRow {
            file_name: format!("{uuid}.1"),
            part_no: 0,
            data_size: legacy_help.len() as i64,
            binary_hex: encode_hex_for_test(&legacy_help),
        },
        ConfigRow {
            file_name: format!("{uuid}.5"),
            part_no: 0,
            data_size: current_help.len() as i64,
            binary_hex: encode_hex_for_test(&current_help),
        },
    ];

    let dumped = dump_table_rows(&root, "Config", rows, false, false, true).unwrap();

    assert_eq!(dumped.source_asset_rows, 1);
    assert_eq!(
        fs::read(root.join("Catalogs/Products/Ext/Help/ru.html")).unwrap(),
        b"new"
    );
    assert_eq!(
        dumped
            .rows
            .iter()
            .find(|row| row.file_name == format!("{uuid}.1"))
            .unwrap()
            .source_asset_path,
        None
    );
    assert_eq!(
        dumped
            .rows
            .iter()
            .find(|row| row.file_name == format!("{uuid}.5"))
            .unwrap()
            .source_asset_path
            .as_deref(),
        Some("Catalogs/Products/Ext/Help.xml")
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn writes_predefined_data_to_source_layout() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-mssql-dump-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    fs::create_dir_all(&root).unwrap();
    let catalog_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let type_uuid = "ae135932-4f94-44df-92c1-c91f15a92848";
    let folder_uuid = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let item_uuid = "cccccccc-cccc-4ccc-cccc-cccccccccccc";
    let catalog_metadata = deflate_for_test(
        catalog_metadata_text_for_test("57", catalog_uuid, "Products", &[], &[]).as_bytes(),
    );
    let predefined = deflate_for_test(
            format!(
                "{{0,{{1,{{7}},{{2,{{1,1,{{2,0,5,{{\"#\",{type_uuid},{{1,00000000-0000-0000-0000-000000000000}}}},{{\"B\",1}},{{\"#\",{type_uuid},{{1,00000000-0000-0000-0000-000000000000}}}},{{\"S\",\"Элементы\"}},{{\"S\",\"\"}},1,{{1,1,{{2,1,7,{{\"#\",{type_uuid},{{1,{folder_uuid}}}}},{{\"B\",1}},{{\"#\",{type_uuid},{{1,00000000-0000-0000-0000-000000000000}}}},{{\"S\",\"Folder\"}},{{\"S\",\"F\"}},{{\"S\",\"Folder description\"}},{{\"N\",0}},1,{{1,1,{{2,2,7,{{\"#\",{type_uuid},{{1,{item_uuid}}}}},{{\"B\",0}},{{\"#\",{type_uuid},{{1,00000000-0000-0000-0000-000000000000}}}},{{\"S\",\"Item\"}},{{\"S\",\"I\"}},{{\"S\",\"Item description\"}},{{\"N\",0}},0}}}}}}}}}}}}}},-1,3}}}}"
            )
            .as_bytes(),
        );
    assert!(parse_predefined_data_blob(&predefined, &BTreeMap::new()).is_some());
    let rows = vec![
        ConfigRow {
            file_name: catalog_uuid.to_string(),
            part_no: 0,
            data_size: catalog_metadata.len() as i64,
            binary_hex: encode_hex_for_test(&catalog_metadata),
        },
        ConfigRow {
            file_name: format!("{catalog_uuid}.1c"),
            part_no: 0,
            data_size: predefined.len() as i64,
            binary_hex: encode_hex_for_test(&predefined),
        },
    ];

    let dumped = dump_table_rows(&root, "Config", rows, false, false, true).unwrap();

    assert_eq!(dumped.metadata_xml_rows, 1);
    assert_eq!(dumped.source_asset_rows, 1);
    let xml = fs::read_to_string(root.join("Catalogs/Products/Ext/Predefined.xml")).unwrap();
    assert!(xml.contains(r#"xsi:type="CatalogPredefinedItems""#));
    assert!(xml.contains(&format!(r#"<Item id="{folder_uuid}">"#)));
    assert!(xml.contains("<Name>Folder</Name>"));
    assert!(xml.contains("<Code>F</Code>"));
    assert!(xml.contains("<Description>Folder description</Description>"));
    assert!(xml.contains("<IsFolder>true</IsFolder>"));
    assert!(xml.contains(&format!(r#"<Item id="{item_uuid}">"#)));
    assert!(xml.contains("<Name>Item</Name>"));
    assert!(xml.contains("<IsFolder>false</IsFolder>"));
    let predefined_row = dumped
        .rows
        .iter()
        .find(|row| row.file_name == format!("{catalog_uuid}.1c"))
        .unwrap();
    assert_eq!(
        predefined_row.source_asset_path.as_deref(),
        Some("Catalogs/Products/Ext/Predefined.xml")
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn non_streamed_information_register_resolves_predefined_design_time_refs() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-mssql-dump-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    let baseline_root = std::env::temp_dir().join(format!(
        "ibcmd-rs-mssql-dump-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    fs::create_dir_all(&root).unwrap();
    fs::create_dir_all(&baseline_root).unwrap();

    let catalog_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let catalog_object_type_id = "11111111-1111-4111-8111-111111111111";
    let catalog_object_value_id = "11111111-1111-4111-8111-111111111112";
    let catalog_ref_type_id = "22222222-2222-4222-8222-222222222221";
    let catalog_ref_value_id = "22222222-2222-4222-8222-222222222222";
    let catalog_selection_type_id = "33333333-3333-4333-8333-333333333331";
    let catalog_selection_value_id = "33333333-3333-4333-8333-333333333332";
    let catalog_list_type_id = "44444444-4444-4444-8444-444444444441";
    let catalog_list_value_id = "44444444-4444-4444-8444-444444444442";
    let catalog_manager_type_id = "55555555-5555-4555-8555-555555555551";
    let catalog_manager_value_id = "55555555-5555-4555-8555-555555555552";
    let item_uuid = "66666666-6666-4666-8666-666666666666";
    let predefined_type_uuid = "ae135932-4f94-44df-92c1-c91f15a92848";
    let register_uuid = "77777777-7777-4777-8777-777777777777";
    let resource_uuid = "88888888-8888-4888-8888-888888888888";

    // Catalog goes through the strict `OwnerGraphFamily` decoder — the old
    // flat/positional shape here predates that refactor (same root cause
    // fixed repeatedly in Cluster 11 via `exact_catalog_owner_fixture_for_test`).
    let (_header, mut catalog_fields, catalog_collections) =
        exact_catalog_owner_fixture_for_test(catalog_uuid, "Products", "");
    for (field_index, value) in [
        (1, catalog_object_type_id),
        (2, catalog_object_value_id),
        (3, catalog_ref_type_id),
        (4, catalog_ref_value_id),
        (5, catalog_selection_type_id),
        (6, catalog_selection_value_id),
        (7, catalog_list_type_id),
        (8, catalog_list_value_id),
        (34, catalog_manager_type_id),
        (35, catalog_manager_value_id),
    ] {
        catalog_fields[field_index] = value.to_owned();
    }
    let catalog_raw = render_owner_graph_fixture_for_test(&catalog_fields, &catalog_collections);
    let catalog_metadata = deflate_for_test(catalog_raw.as_bytes());
    let predefined = deflate_for_test(
        format!(
            "{{0,{{1,{{7}},{{2,{{1,1,{{2,0,5,{{\"#\",{predefined_type_uuid},{{1,00000000-0000-0000-0000-000000000000}}}},{{\"B\",1}},{{\"#\",{predefined_type_uuid},{{1,00000000-0000-0000-0000-000000000000}}}},{{\"S\",\"Items\"}},{{\"S\",\"\"}},1,{{1,1,{{2,1,7,{{\"#\",{predefined_type_uuid},{{1,{item_uuid}}}}},{{\"B\",0}},{{\"#\",{predefined_type_uuid},{{1,00000000-0000-0000-0000-000000000000}}}},{{\"S\",\"Item\"}},{{\"S\",\"I\"}},{{\"S\",\"Item\"}},{{\"N\",0}},0}}}}}}}}}}}}}},-1,3}}}}"
        )
        .as_bytes(),
    );

    let mut common_fields = split_1c_braced_fields(
        &information_register_common_child_for_test(resource_uuid),
        0,
    )
    .unwrap()
    .into_iter()
    .map(str::to_string)
    .collect::<Vec<_>>();
    common_fields[16] = format!(
        "{{0,1,\"Filter.Owner\",{{\"#\",{DESIGN_TIME_REF_TYPE_UUID},{{0,{catalog_ref_type_id},{item_uuid}}}}}}}"
    );
    let common = format!("{{{}}}", common_fields.join(","));
    let register_metadata = deflate_for_test(
        format!(
            "{{1,{{33,90000000-0000-4000-8000-000000000001,90000000-0000-4000-8000-000000000002,90000000-0000-4000-8000-000000000003,90000000-0000-4000-8000-000000000004,90000000-0000-4000-8000-000000000005,90000000-0000-4000-8000-000000000006,90000000-0000-4000-8000-000000000007,90000000-0000-4000-8000-000000000008,90000000-0000-4000-8000-000000000009,90000000-0000-4000-8000-000000000010,90000000-0000-4000-8000-000000000011,90000000-0000-4000-8000-000000000012,90000000-0000-4000-8000-000000000013,90000000-0000-4000-8000-000000000014,{{0,{{3,{{1,0,{register_uuid}}},\"Rates\",{{1,\"en\",\"Rates\"}},\"\"}},{{7,{common},0,1,1}}}}}}}}"
        )
        .as_bytes(),
    );
    let row = |file_name: String, data: &Vec<u8>| ConfigRow {
        file_name,
        part_no: 0,
        data_size: data.len() as i64,
        binary_hex: encode_hex_for_test(data),
    };
    let non_ir_rows = vec![
        row(catalog_uuid.to_string(), &catalog_metadata),
        row(format!("{catalog_uuid}.1c"), &predefined),
    ];
    dump_table_rows_with_source_version(
        &baseline_root,
        "Config",
        non_ir_rows.clone(),
        false,
        false,
        true,
        InfobaseConfigSourceVersion::V2_21,
    )
    .unwrap();
    let mut rows = non_ir_rows;
    rows.push(row(register_uuid.to_string(), &register_metadata));
    let dumped = dump_table_rows_with_source_version(
        &root,
        "Config",
        rows,
        false,
        false,
        true,
        InfobaseConfigSourceVersion::V2_21,
    )
    .unwrap();

    assert_eq!(dumped.metadata_xml_rows, 2);
    let register_xml = fs::read_to_string(root.join("InformationRegisters/Rates.xml")).unwrap();
    assert!(
        register_xml.contains(
            r#"<app:value xsi:type="xr:DesignTimeRef">Catalog.Products.Item</app:value>"#
        )
    );
    assert_eq!(
        fs::read(root.join("Catalogs/Products.xml")).unwrap(),
        fs::read(baseline_root.join("Catalogs/Products.xml")).unwrap()
    );
    assert_eq!(
        fs::read(root.join("Catalogs/Products/Ext/Predefined.xml")).unwrap(),
        fs::read(baseline_root.join("Catalogs/Products/Ext/Predefined.xml")).unwrap()
    );

    let _ = fs::remove_dir_all(root);
    let _ = fs::remove_dir_all(baseline_root);
}

#[test]
