#[test]
fn writes_template_metadata_xml_to_owner_or_common_template_layout() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-mssql-dump-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    fs::create_dir_all(&root).unwrap();
    let catalog_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let owned_template_uuid = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let common_template_uuid = "cccccccc-cccc-4ccc-cccc-cccccccccccc";
    let catalog_metadata = deflate_for_test(
        catalog_metadata_text_for_test("57", catalog_uuid, "Products", &[], &[owned_template_uuid])
            .as_bytes(),
    );
    let owned_template_metadata = deflate_for_test(
            format!(
                "{{1,\r\n{{2,0,\r\n{{3,\r\n{{1,0,{owned_template_uuid}}},\"Print\",{{1,\"en\",\"Print\"}},\"\"}}\r\n,0}}\r\n}}"
            )
            .as_bytes(),
        );
    let owned_template_body = pack_moxel_spreadsheet_blob_from_xml(
        br#"<?xml version="1.0" encoding="UTF-8"?>
<document xmlns="http://v8.1c.ru/8.2/data/spreadsheet" xmlns:v8="http://v8.1c.ru/8.1/data/core">
	<columns>
		<size>1</size>
	</columns>
	<rowsItem>
		<index>0</index>
		<row>
			<c>
				<i>2</i>
				<c>
					<f>0</f>
					<tl>
						<v8:item>
							<v8:lang>ru</v8:lang>
							<v8:content>Hello &quot;Name&quot; &amp; &lt;Tag&gt;</v8:content>
						</v8:item>
					</tl>
				</c>
			</c>
		</row>
	</rowsItem>
</document>
"#,
    )
    .unwrap()
    .blob;
    let common_template_metadata = deflate_for_test(
            format!(
                "{{1,\r\n{{4,\r\n{{3,\r\n{{1,0,{common_template_uuid}}},\"SharedText\",{{1,\"en\",\"Shared text\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},4}},0}}"
            )
            .as_bytes(),
        );
    let common_template_body = deflate_for_test(b"\xef\xbb\xbfPlain text");
    let rows = vec![
        ConfigRow {
            file_name: catalog_uuid.to_string(),
            part_no: 0,
            data_size: catalog_metadata.len() as i64,
            binary_hex: encode_hex_for_test(&catalog_metadata),
        },
        ConfigRow {
            file_name: owned_template_uuid.to_string(),
            part_no: 0,
            data_size: owned_template_metadata.len() as i64,
            binary_hex: encode_hex_for_test(&owned_template_metadata),
        },
        ConfigRow {
            file_name: format!("{owned_template_uuid}.0"),
            part_no: 0,
            data_size: owned_template_body.len() as i64,
            binary_hex: encode_hex_for_test(&owned_template_body),
        },
        ConfigRow {
            file_name: common_template_uuid.to_string(),
            part_no: 0,
            data_size: common_template_metadata.len() as i64,
            binary_hex: encode_hex_for_test(&common_template_metadata),
        },
        ConfigRow {
            file_name: format!("{common_template_uuid}.0"),
            part_no: 0,
            data_size: common_template_body.len() as i64,
            binary_hex: encode_hex_for_test(&common_template_body),
        },
    ];

    let dumped = dump_table_rows(&root, "Config", rows, false, false, true).unwrap();

    assert_eq!(dumped.metadata_xml_rows, 3);
    assert_eq!(dumped.source_asset_rows, 2);
    let owned_xml = fs::read_to_string(root.join("Catalogs/Products/Templates/Print.xml")).unwrap();
    let common_xml = fs::read_to_string(root.join("CommonTemplates/SharedText.xml")).unwrap();
    let common_body = fs::read(root.join("CommonTemplates/SharedText/Ext/Template.txt")).unwrap();
    let template_body =
        fs::read_to_string(root.join("Catalogs/Products/Templates/Print/Ext/Template.xml"))
            .unwrap();
    assert!(owned_xml.contains("<Template uuid=\"bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb\">"));
    assert!(owned_xml.starts_with('\u{feff}'));
    assert!(owned_xml.contains(r#"xmlns:app="http://v8.1c.ru/8.2/managed-application/core""#));
    assert!(owned_xml.contains(r#"version="2.20""#));
    assert!(owned_xml.contains("<Comment/>"));
    assert!(!owned_xml.contains("<Comment></Comment>"));
    assert!(!owned_xml.ends_with("\r\n"));
    assert!(owned_xml.contains("<TemplateType>SpreadsheetDocument</TemplateType>"));
    assert!(template_body.contains("<document xmlns=\"http://v8.1c.ru/8.2/data/spreadsheet\""));
    assert!(template_body.contains("<v8:content>Hello \"Name\" &amp; &lt;Tag&gt;</v8:content>"));
    assert!(!template_body.contains("&quot;Name&quot;"));
    assert!(template_body.contains("<i>2</i>"));
    assert!(common_xml.contains("<CommonTemplate uuid=\"cccccccc-cccc-4ccc-cccc-cccccccccccc\">"));
    assert!(common_xml.starts_with('\u{feff}'));
    assert!(common_xml.contains(r#"xmlns:app="http://v8.1c.ru/8.2/managed-application/core""#));
    assert!(common_xml.contains("<Comment/>"));
    assert!(!common_xml.contains("<Comment></Comment>"));
    assert!(!common_xml.ends_with("\r\n"));
    assert!(common_xml.contains("<TemplateType>TextDocument</TemplateType>"));
    assert_eq!(common_body, b"\xef\xbb\xbfPlain text");
    let template_row = dumped
        .rows
        .iter()
        .find(|row| row.file_name == owned_template_uuid)
        .unwrap();
    assert_eq!(
        template_row.metadata_xml_path.as_deref(),
        Some("Catalogs/Products/Templates/Print.xml")
    );
    let body_row = dumped
        .rows
        .iter()
        .find(|row| row.file_name == format!("{common_template_uuid}.0"))
        .unwrap();
    assert_eq!(
        body_row.source_asset_path.as_deref(),
        Some("CommonTemplates/SharedText/Ext/Template.txt")
    );
    let spreadsheet_body_row = dumped
        .rows
        .iter()
        .find(|row| row.file_name == format!("{owned_template_uuid}.0"))
        .unwrap();
    assert_eq!(
        spreadsheet_body_row.source_asset_path.as_deref(),
        Some("Catalogs/Products/Templates/Print/Ext/Template.xml")
    );

    let _ = fs::remove_dir_all(root);
}

/// End-to-end regression for the `extra` Template.txt defect (`output-
/// path-collisions-and-module-text-fallback-20260825.md` section 4, real
/// ERP UH bytes): an owned Template whose body is the brace-tuple
/// `GraphicalSchema` grammar (not pre-serialized XML) must land at
/// `Templates/<name>/Ext/Template.xml` with real decoded content -- the
/// platform's own path and format -- not at `Templates/<name>/Ext/
/// Template.txt` as raw undecoded text, which is a path the platform never
/// produces and was every one of that corpus's 64 `extra` files.
#[test]
fn writes_graphical_scheme_template_body_to_ext_template_xml() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-mssql-dump-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    fs::create_dir_all(&root).unwrap();
    let catalog_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let template_uuid = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let start_uuid = "cccccccc-cccc-4ccc-cccc-cccccccccccc";
    let catalog_metadata = deflate_for_test(
        catalog_metadata_text_for_test("57", catalog_uuid, "Products", &[], &[template_uuid])
            .as_bytes(),
    );
    // The `template_type_code` slot (the "5" below) is deliberately a value
    // `template_type_from_code` does not map (`refs.rs`'s only mapped codes
    // are 0/1/3/4/6/7/9): this test is about body-content sniffing picking
    // `GraphicalSchema` for the brace-tuple body, which only runs when the
    // header carries no recognized type hint.
    let template_metadata = deflate_for_test(
        format!(
            "{{1,\r\n{{2,5,\r\n{{3,\r\n{{1,0,{template_uuid}}},\"Scheme\",{{1,\"en\",\"Scheme\"}},\"\"}}\r\n,0}}\r\n}}"
        )
        .as_bytes(),
    );
    let scheme_header = r#"{1,{3,3,{-10}},0,20,20,3,6,6,{"N",10},7,{"N",10},8,{"N",10},9,{"N",10},13,{"N",0},16,{"N",0}}"#;
    // The same evidenced Start-item shape `writes_business_process_
    // flowchart_to_source_layout` uses (real `BusinessProcess.Flowchart`
    // grammar, proven to parse): style/geometry/shape unchanged, just one
    // item instead of three.
    let style = "{7,{3,4,{0}},{3,3,{-22}},{3,3,{-3}},{7,1,0,{0},1,100},{1,0},1,1,1,0,0,0,0,0}";
    let border = "{4,0,{0},1,1,0,e45c0cd8-a878-4bcb-8e1a-af934481e1cc,0}";
    let picture = "{4,0,{0},\"\",-1,-1,1,0,\"\"}";
    let start_head = format!(r#"{{{{4,1,{{1,0}},"Start",1}},4,{start_uuid},0}}"#);
    let start_geometry =
        format!("{{{style},5,10,20,50,60,4,10,20,49,20,49,59,10,59,4,{picture},{border}}}");
    let start_shape = format!("{{{{{start_geometry},1}}}}");
    let start_item = format!("{{{start_head},2,{start_shape},{{0}}}}");
    let plain_text = format!("{{5,{{{scheme_header}}},1,2,{start_item},4}}");
    let template_body = deflate_for_test(plain_text.as_bytes());
    let rows = vec![
        ConfigRow {
            file_name: catalog_uuid.to_string(),
            part_no: 0,
            data_size: catalog_metadata.len() as i64,
            binary_hex: encode_hex_for_test(&catalog_metadata),
        },
        ConfigRow {
            file_name: template_uuid.to_string(),
            part_no: 0,
            data_size: template_metadata.len() as i64,
            binary_hex: encode_hex_for_test(&template_metadata),
        },
        ConfigRow {
            file_name: format!("{template_uuid}.0"),
            part_no: 0,
            data_size: template_body.len() as i64,
            binary_hex: encode_hex_for_test(&template_body),
        },
    ];

    let dumped = dump_table_rows(&root, "Config", rows, false, false, true).unwrap();

    assert!(
        !root
            .join("Catalogs/Products/Templates/Scheme/Ext/Template.txt")
            .exists(),
        "must not fall back to the TextDocument path the platform never produces"
    );
    let template_xml =
        fs::read_to_string(root.join("Catalogs/Products/Templates/Scheme/Ext/Template.xml"))
            .unwrap();
    assert!(template_xml.contains(r#"<GraphicalSchema xmlns="http://v8.1c.ru/8.3/xcf/scheme""#));
    assert!(template_xml.contains(&format!(r#"<Start id="1" uuid="{start_uuid}">"#)));
    let body_row = dumped
        .rows
        .iter()
        .find(|row| row.file_name == format!("{template_uuid}.0"))
        .unwrap();
    assert_eq!(
        body_row.source_asset_path.as_deref(),
        Some("Catalogs/Products/Templates/Scheme/Ext/Template.xml")
    );

    let _ = fs::remove_dir_all(root);
}

