#[test]
fn extracts_accumulation_register_type_from_metadata_body() {
    let register_uuid = "11111111-1111-4111-8111-111111111111";
    let zero_uuid = "00000000-0000-0000-0000-000000000000";

    for (type_value, expected_type) in [(0, "Balance"), (1, "Turnovers")] {
        let blob = deflate_for_test(
                format!(
                    "{{1,\r\n{{28,22222222-2222-4222-8222-222222222221,22222222-2222-4222-8222-222222222222,\
33333333-3333-4333-8333-333333333331,33333333-3333-4333-8333-333333333332,\
44444444-4444-4444-8444-444444444441,44444444-4444-4444-8444-444444444442,\
55555555-5555-4555-8555-555555555551,55555555-5555-4555-8555-555555555552,\
66666666-6666-4666-8666-666666666661,66666666-6666-4666-8666-666666666662,\
77777777-7777-4777-8777-777777777771,77777777-7777-4777-8777-777777777772,\r\n\
{{3,\r\n{{1,0,{register_uuid}}},\"Sales\",{{1,\"en\",\"Sales\"}},\"\"}},1,{zero_uuid},{zero_uuid},{type_value}\r\n}}\r\n}}"
                )
                .as_bytes(),
            );

        let extracted = extract_metadata_source_xml_with_refs(
            &blob,
            register_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            InfobaseConfigSourceVersion::V2_21,
        )
        .unwrap();
        let xml = String::from_utf8(extracted.xml).unwrap();

        assert_eq!(
            extracted.relative_path,
            PathBuf::from("AccumulationRegisters/Sales.xml")
        );
        assert!(xml.contains(&format!("<RegisterType>{expected_type}</RegisterType>")));
        assert!(xml.contains("<DefaultListForm/>"));
        assert!(xml.contains("<AuxiliaryListForm/>"));
        assert!(
            xml.find("<UseStandardCommands>true</UseStandardCommands>")
                .unwrap()
                < xml.find("<DefaultListForm/>").unwrap()
        );
        assert!(
            xml.find("<DefaultListForm/>").unwrap() < xml.find("<AuxiliaryListForm/>").unwrap()
        );
        assert!(xml.find("<AuxiliaryListForm/>").unwrap() < xml.find("<RegisterType>").unwrap());
        assert!(
            xml.find("<RegisterType>").unwrap()
                < xml
                    .find("<IncludeHelpInContents>false</IncludeHelpInContents>")
                    .unwrap()
        );
        assert!(!xml.contains("ConfigDumpInfo"));
        if expected_type == "Turnovers" {
            assert!(!xml.contains(r#"<xr:StandardAttribute name="RecordType">"#));
            assert_eq!(xml.matches("<xr:StandardAttribute").count(), 4);
        }
    }
}

#[test]
fn extracts_accumulation_register_list_form_refs_from_metadata_body() {
    let register_uuid = "11111111-1111-4111-8111-111111111111";
    let default_list_form_uuid = "22222222-2222-4222-8222-222222222222";
    let auxiliary_list_form_uuid = "33333333-3333-4333-8333-333333333333";
    let blob = deflate_for_test(
            format!(
                "{{1,\r\n{{28,aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaa1,aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaa2,\
bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbb1,bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbb2,\
cccccccc-cccc-4ccc-cccc-ccccccccccc1,cccccccc-cccc-4ccc-cccc-ccccccccccc2,\
dddddddd-dddd-4ddd-dddd-ddddddddddd1,dddddddd-dddd-4ddd-dddd-ddddddddddd2,\
eeeeeeee-eeee-4eee-eeee-eeeeeeeeeee1,eeeeeeee-eeee-4eee-eeee-eeeeeeeeeee2,\
ffffffff-ffff-4fff-ffff-fffffffffff1,ffffffff-ffff-4fff-ffff-fffffffffff2,\r\n\
{{3,\r\n{{1,0,{register_uuid}}},\"Sales\",{{1,\"en\",\"Sales\"}},\"\"}},1,\
{default_list_form_uuid},{auxiliary_list_form_uuid},0,1,1,0\r\n}}\r\n}}"
            )
            .as_bytes(),
        );
    let form_refs = BTreeMap::from([
        (
            default_list_form_uuid.to_string(),
            FormSourceReference {
                relative_path: PathBuf::from("AccumulationRegisters/Sales/Forms/List.xml"),
                kind: "Form",
            },
        ),
        (
            auxiliary_list_form_uuid.to_string(),
            FormSourceReference {
                relative_path: PathBuf::from("AccumulationRegisters/Sales/Forms/AuxiliaryList.xml"),
                kind: "Form",
            },
        ),
    ]);

    let extracted = extract_metadata_source_xml_with_refs(
        &blob,
        register_uuid,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &form_refs,
        &BTreeMap::new(),
        &BTreeMap::new(),
        InfobaseConfigSourceVersion::V2_21,
    )
    .unwrap();
    let xml = String::from_utf8(extracted.xml).unwrap();

    assert!(
        xml.contains("<DefaultListForm>AccumulationRegister.Sales.Form.List</DefaultListForm>")
    );
    assert!(xml.contains(
        "<AuxiliaryListForm>AccumulationRegister.Sales.Form.AuxiliaryList</AuxiliaryListForm>"
    ));
    assert!(
        xml.find("<UseStandardCommands>true</UseStandardCommands>")
            .unwrap()
            < xml.find("<DefaultListForm>").unwrap()
    );
    assert!(xml.find("<AuxiliaryListForm>").unwrap() < xml.find("<RegisterType>").unwrap());
}

