#[test]
fn rejects_settings_storage_default_form_outside_unique_owner_collection() {
    let owner_uuid = uuid::Uuid::new_v4().hyphenated().to_string();
    let manager_type_id = uuid::Uuid::new_v4().hyphenated().to_string();
    let manager_value_id = uuid::Uuid::new_v4().hyphenated().to_string();
    let default_form_uuid = uuid::Uuid::new_v4().hyphenated().to_string();
    let other_form_uuid = uuid::Uuid::new_v4().hyphenated().to_string();

    let other_forms = [other_form_uuid.as_str()];
    let missing_from_collection =
        settings_storage_raw_for_forms_test(&settings_storage_test_options(
            &owner_uuid,
            &manager_type_id,
            &manager_value_id,
            &default_form_uuid,
            ZERO_UUID_FOR_SETTINGS_STORAGE_TEST,
            &other_forms,
        ));
    let missing_refs = settings_storage_form_refs_for_test(
        "UserSettings",
        &[
            (&default_form_uuid, "LoadForm"),
            (&other_form_uuid, "OtherForm"),
        ],
    );
    assert!(
        parse_settings_storage_properties_from_text(
            &missing_from_collection,
            &owner_uuid,
            &missing_refs,
        )
        .is_none()
    );

    let owner_forms = [default_form_uuid.as_str()];
    let owned_raw = settings_storage_raw_for_forms_test(&settings_storage_test_options(
        &owner_uuid,
        &manager_type_id,
        &manager_value_id,
        &default_form_uuid,
        ZERO_UUID_FOR_SETTINGS_STORAGE_TEST,
        &owner_forms,
    ));
    for form_ref in [
        FormSourceReference {
            relative_path: PathBuf::from("SettingsStorages")
                .join("OtherStorage")
                .join("Forms")
                .join("LoadForm.xml"),
            kind: "Form",
        },
        FormSourceReference {
            relative_path: PathBuf::from("CommonForms").join("LoadForm.xml"),
            kind: "CommonForm",
        },
        FormSourceReference {
            relative_path: PathBuf::from("SettingsStorages")
                .join("UserSettings")
                .join("Forms")
                .join(".xml"),
            kind: "Form",
        },
        FormSourceReference {
            relative_path: PathBuf::from("SettingsStorages")
                .join("UserSettings")
                .join("Forms")
                .join("Nested")
                .join("LoadForm.xml"),
            kind: "Form",
        },
    ] {
        let refs = BTreeMap::from([(default_form_uuid.clone(), form_ref)]);
        assert!(
            parse_settings_storage_properties_from_text(&owned_raw, &owner_uuid, &refs).is_none()
        );
    }

    let case_collision_uuid = loop {
        let candidate = uuid::Uuid::new_v4().hyphenated().to_string();
        if candidate.to_ascii_uppercase() != candidate {
            break candidate;
        }
    };
    let collision_forms = [case_collision_uuid.as_str()];
    let collision_raw = settings_storage_raw_for_forms_test(&settings_storage_test_options(
        &owner_uuid,
        &manager_type_id,
        &manager_value_id,
        &case_collision_uuid,
        ZERO_UUID_FOR_SETTINGS_STORAGE_TEST,
        &collision_forms,
    ));
    let collision_path = PathBuf::from("SettingsStorages")
        .join("UserSettings")
        .join("Forms")
        .join("LoadForm.xml");
    let collision_refs = BTreeMap::from([
        (
            case_collision_uuid.clone(),
            FormSourceReference {
                relative_path: collision_path.clone(),
                kind: "Form",
            },
        ),
        (
            case_collision_uuid.to_ascii_uppercase(),
            FormSourceReference {
                relative_path: collision_path,
                kind: "Form",
            },
        ),
    ]);
    assert!(
        parse_settings_storage_properties_from_text(&collision_raw, &owner_uuid, &collision_refs,)
            .is_none()
    );
}

#[test]
fn extracts_additional_simple_service_metadata_xml_from_blobs() {
    let language_uuid = "11111111-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    let language_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{0,\r\n{{3,\r\n{{1,0,{language_uuid}}},\"English\",{{1,\"en\",\"English\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},\"en\"}},0}}"
            )
            .as_bytes(),
        );
    let xdto_uuid = "22222222-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    let xdto_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{1,\r\n{{3,\r\n{{1,0,{xdto_uuid}}},\"Exchange\",{{1,\"en\",\"Exchange\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},\"http://example.com/exchange\"}},0}}"
            )
            .as_bytes(),
        );
    let http_uuid = "33333333-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    let url_template_uuid = "33333333-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
    let method_uuid = "33333333-cccc-4ccc-8ccc-cccccccccccc";
    let http_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{2,\"api\",\r\n{{3,\r\n{{1,0,{http_uuid}}},\"Api\",{{1,\"en\",\"API\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},2,20,\r\n{{0,1,\r\n{{7,\r\n{{3,\r\n{{1,0,{url_template_uuid}}},\"Any\",{{1,\"en\",\"Any\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},\"/*\",\r\n{{0,1,\r\n{{8,\r\n{{3,\r\n{{1,0,{method_uuid}}},\"Post\",{{1,\"en\",\"Post\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},\"POST\",\"HandlePost\"}}\r\n}}\r\n}}\r\n}}\r\n}},0}}"
            )
            .as_bytes(),
        );
    let storage_uuid = "44444444-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    let storage_raw = settings_storage_raw_for_forms_test(&settings_storage_test_options(
        storage_uuid,
        "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
        "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
        ZERO_UUID_FOR_SETTINGS_STORAGE_TEST,
        ZERO_UUID_FOR_SETTINGS_STORAGE_TEST,
        &[],
    ));
    let storage_blob = deflate_for_test(storage_raw.as_bytes());
    let job_uuid = "55555555-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    let job_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{2,\r\n{{3,\r\n{{1,0,{job_uuid}}},\"LoadRates\",{{1,\"en\",\"Load rates\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},\"\",\"Load rates\",1,1,aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa,\"LoadRates\",3,10}},0}}"
            )
            .as_bytes(),
        );

    for (blob, uuid, expected_kind, expected_path) in [
        (
            &language_blob,
            language_uuid,
            "Language",
            PathBuf::from("Languages").join("English.xml"),
        ),
        (
            &xdto_blob,
            xdto_uuid,
            "XDTOPackage",
            PathBuf::from("XDTOPackages").join("Exchange.xml"),
        ),
        (
            &http_blob,
            http_uuid,
            "HTTPService",
            PathBuf::from("HTTPServices").join("Api.xml"),
        ),
        (
            &storage_blob,
            storage_uuid,
            "SettingsStorage",
            PathBuf::from("SettingsStorages").join("UserSettings.xml"),
        ),
        (
            &job_blob,
            job_uuid,
            "ScheduledJob",
            PathBuf::from("ScheduledJobs").join("LoadRates.xml"),
        ),
    ] {
        let extracted = extract_metadata_source_xml(
            blob,
            uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .unwrap();
        let properties = parse_simple_metadata_xml_properties(&extracted.xml).unwrap();
        let repacked = pack_simple_metadata_blob_from_xml(blob, &extracted.xml).unwrap();

        assert_eq!(extracted.relative_path, expected_path);
        assert_eq!(properties.kind, expected_kind);
        assert_eq!(properties.uuid, uuid);
        if expected_kind == "XDTOPackage" {
            let xml = String::from_utf8(extracted.xml.clone()).unwrap();
            assert!(xml.contains("<Namespace>http://example.com/exchange</Namespace>"));
            assert!(xml.contains(r#"version="2.20""#));
            let extracted_v21 = extract_metadata_source_xml_with_refs(
                blob,
                uuid,
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                InfobaseConfigSourceVersion::V2_21,
            )
            .unwrap();
            let xml_v21 = String::from_utf8(extracted_v21.xml).unwrap();
            assert!(xml_v21.contains("<Namespace>http://example.com/exchange</Namespace>"));
            assert!(xml_v21.contains(r#"version="2.21""#));
            assert!(!xml_v21.contains(r#"version="2.20""#));
        }
        if expected_kind == "HTTPService" {
            let xml = String::from_utf8(extracted.xml.clone()).unwrap();
            assert!(xml.contains("<RootURL>api</RootURL>"));
            assert!(xml.contains("<ReuseSessions>AutoUse</ReuseSessions>"));
            assert!(xml.contains("<SessionMaxAge>20</SessionMaxAge>"));
            assert!(xml.contains(&format!(r#"<URLTemplate uuid="{url_template_uuid}">"#)));
            assert!(xml.contains("<Template>/*</Template>"));
            assert!(xml.contains(&format!(r#"<Method uuid="{method_uuid}">"#)));
            assert!(xml.contains("<HTTPMethod>POST</HTTPMethod>"));
            assert!(xml.contains("<Handler>HandlePost</Handler>"));

            let extracted_v21 = extract_metadata_source_xml_with_refs(
                blob,
                uuid,
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                &BTreeMap::new(),
                InfobaseConfigSourceVersion::V2_21,
            )
            .unwrap();
            let xml_v21 = String::from_utf8(extracted_v21.xml).unwrap();
            assert!(xml_v21.contains("<RootURL>api</RootURL>"));
            assert!(xml_v21.contains(r#"version="2.21""#));
            assert!(!xml_v21.contains(r#"version="2.20""#));
        }
        assert!(!repacked.blob.is_empty());
    }
}

#[test]
fn extracts_http_service_xml_from_real_layout_wrappers() {
    let service_uuid = "33333333-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    let url_template_uuid = "33333333-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
    let method_uuid = "33333333-cccc-4ccc-8ccc-cccccccccccc";
    let blob = deflate_for_test(
            format!(
                "{{1,\r\n{{2,\"edi\",\r\n{{3,\r\n{{1,0,{service_uuid}}},\"Api\",{{1,\"en\",\"API\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},2,20}},1,\r\n{{ec6896c2-9b28-42d8-9140-48491146b8ea,1,\r\n{{\r\n{{0,\"/events/newdocs\",\r\n{{3,\r\n{{1,0,{url_template_uuid}}},\"Any\",{{1,\"en\",\"Any\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}}\r\n}},1,\r\n{{21c96ea8-c8fc-424a-a0b4-e1ffb2fa1a73,1,\r\n{{\r\n{{0,\"HandlePost\",11,\r\n{{3,\r\n{{1,0,{method_uuid}}},\"POST\",{{1,\"en\",\"POST\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}}\r\n}},0}}\r\n}}\r\n}}\r\n}}\r\n}}\r\n}}"
            )
            .as_bytes(),
        );

    let extracted = extract_metadata_source_xml(
        &blob,
        service_uuid,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
    )
    .unwrap();
    let xml = String::from_utf8(extracted.xml).unwrap();

    assert!(xml.contains("<RootURL>edi</RootURL>"));
    assert!(xml.contains(&format!(r#"<URLTemplate uuid="{url_template_uuid}">"#)));
    assert!(xml.contains("<Template>/events/newdocs</Template>"));
    assert!(xml.contains(&format!(r#"<Method uuid="{method_uuid}">"#)));
    assert!(xml.contains("<HTTPMethod>POST</HTTPMethod>"));
    assert!(xml.contains("<Handler>HandlePost</Handler>"));
}

#[test]
fn parses_http_service_url_templates_from_real_layout_text() {
    let service_uuid = "33333333-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    let url_template_uuid = "33333333-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
    let method_uuid = "33333333-cccc-4ccc-8ccc-cccccccccccc";
    let text = format!(
        "{{1,\r\n{{2,\"edi\",\r\n{{3,\r\n{{1,0,{service_uuid}}},\"Api\",{{1,\"en\",\"API\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}},2,20}},1,\r\n{{ec6896c2-9b28-42d8-9140-48491146b8ea,1,\r\n{{\r\n{{0,\"/events/newdocs\",\r\n{{3,\r\n{{1,0,{url_template_uuid}}},\"Any\",{{1,\"en\",\"Any\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}}\r\n}},1,\r\n{{21c96ea8-c8fc-424a-a0b4-e1ffb2fa1a73,1,\r\n{{\r\n{{0,\"HandlePost\",11,\r\n{{3,\r\n{{1,0,{method_uuid}}},\"POST\",{{1,\"en\",\"POST\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}}\r\n}},0}}\r\n}}\r\n}}\r\n}}\r\n}}\r\n}}"
    );

    let nested = nested_headers_with_offsets_from_text(&text, service_uuid, |_| true);
    assert_eq!(nested.len(), 2);

    let candidates = http_service_child_candidates_from_text(&text, service_uuid);
    assert_eq!(candidates.len(), 2);

    let templates = parse_http_service_url_templates_from_text(&text, service_uuid);

    assert_eq!(templates.len(), 1);
    assert_eq!(templates[0].header.uuid, url_template_uuid);
    assert_eq!(templates[0].template, "/events/newdocs");
    assert_eq!(templates[0].methods.len(), 1);
    assert_eq!(templates[0].methods[0].header.uuid, method_uuid);
    assert_eq!(templates[0].methods[0].http_method, "POST");
    assert_eq!(templates[0].methods[0].handler, "HandlePost");
}

