#[test]
fn extracts_catalog_create_and_data_history_tail_to_metadata_xml() {
    let catalog_uuid = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    let object_type_id = "11111111-1111-4111-8111-111111111111";
    let object_value_id = "11111111-1111-4111-8111-111111111112";
    let ref_type_id = "22222222-2222-4222-8222-222222222221";
    let ref_value_id = "22222222-2222-4222-8222-222222222222";
    let selection_type_id = "33333333-3333-4333-8333-333333333331";
    let selection_value_id = "33333333-3333-4333-8333-333333333332";
    let list_type_id = "44444444-4444-4444-8444-444444444441";
    let list_value_id = "44444444-4444-4444-8444-444444444442";
    let manager_type_id = "55555555-5555-4555-8555-555555555551";
    let manager_value_id = "55555555-5555-4555-8555-555555555552";
    let (_header, mut fields, collections) =
        exact_catalog_owner_fixture_for_test(catalog_uuid, "Products", "");
    for (field_index, value) in [
        (1, object_type_id),
        (2, object_value_id),
        (3, ref_type_id),
        (4, ref_value_id),
        (5, selection_type_id),
        (6, selection_value_id),
        (7, list_type_id),
        (8, list_value_id),
        (34, manager_type_id),
        (35, manager_value_id),
    ] {
        fields[field_index] = value.to_owned();
    }
    fields[53] = "2".to_owned();
    fields[57] = "1".to_owned();
    fields[58] = "1".to_owned();
    fields[59] = "1".to_owned();
    fields[60] = "1".to_owned();
    let catalog_raw = render_owner_graph_fixture_for_test(&fields, &collections);
    let catalog_blob = deflate_for_test(catalog_raw.as_bytes());

    let extracted = extract_metadata_source_xml(
        &catalog_blob,
        catalog_uuid,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
    )
    .unwrap();
    let xml = String::from_utf8(extracted.xml).unwrap();

    assert_eq!(
        extracted.relative_path,
        PathBuf::from("Catalogs").join("Products.xml")
    );
    assert!(xml.contains("<CreateOnInput>Use</CreateOnInput>"), "{xml}");
    assert!(
        xml.contains("<ChoiceHistoryOnInput>DontUse</ChoiceHistoryOnInput>"),
        "{xml}"
    );
    assert!(xml.contains("<DataHistory>Use</DataHistory>"), "{xml}");
    assert!(
        xml.contains(
            "<UpdateDataHistoryImmediatelyAfterWrite>true</UpdateDataHistoryImmediatelyAfterWrite>"
        ),
        "{xml}"
    );
    assert!(
            xml.contains(
                "<ExecuteAfterWriteDataHistoryVersionProcessing>true</ExecuteAfterWriteDataHistoryVersionProcessing>"
            ),
            "{xml}"
        );
    assert!(
        xml.find("<Explanation/>").unwrap() < xml.find("<CreateOnInput>").unwrap(),
        "{xml}"
    );
    assert!(
        xml.find("<CreateOnInput>Use</CreateOnInput>").unwrap()
            < xml
                .find("<ChoiceHistoryOnInput>DontUse</ChoiceHistoryOnInput>")
                .unwrap(),
        "{xml}"
    );
    assert!(
        xml.find("<ChoiceHistoryOnInput>DontUse</ChoiceHistoryOnInput>")
            .unwrap()
            < xml.find("<DataHistory>Use</DataHistory>").unwrap(),
        "{xml}"
    );
    assert!(
            xml.find("<DataHistory>Use</DataHistory>").unwrap()
                < xml
                    .find(
                        "<UpdateDataHistoryImmediatelyAfterWrite>true</UpdateDataHistoryImmediatelyAfterWrite>",
                    )
                    .unwrap(),
            "{xml}"
        );
    assert!(
            xml.find(
                "<UpdateDataHistoryImmediatelyAfterWrite>true</UpdateDataHistoryImmediatelyAfterWrite>",
            )
            .unwrap()
                < xml
                    .find(
                        "<ExecuteAfterWriteDataHistoryVersionProcessing>true</ExecuteAfterWriteDataHistoryVersionProcessing>",
                    )
                    .unwrap(),
            "{xml}"
        );
}

