#[test]
fn characteristics_all_three_owner_slots_decode_render_and_invalid_cct_is_typed() {
    let raw = collection(&item(
        "4",
        DOCUMENT_CHARACTERISTIC_TYPE_UUID,
        r#"{"S","safe"}"#,
    ));
    for family in [
        OwnerGraphFamily::Catalog,
        OwnerGraphFamily::Document,
        OwnerGraphFamily::ChartOfCharacteristicTypes,
    ] {
        let slot = characteristics_slot(family.into());
        let mut owned_fields = vec!["0".to_owned(); family.layout().owner_field_count];
        owned_fields[slot] = raw.clone();
        let fields = owned_fields.iter().map(String::as_str).collect::<Vec<_>>();
        let mut diagnostic = None;
        let model = decode_owner_characteristics(
            family.into(),
            &fields,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &references(),
            &mut diagnostic,
        )
        .unwrap();
        assert!(diagnostic.is_none());
        let xml = ibcmd_xml::render_characteristics_xml(&model, "\t\t\t").unwrap();
        let ordered = [
            "CharacteristicTypes",
            "KeyField",
            "TypesFilterField",
            "TypesFilterValue",
            "DataPathField",
            "MultipleValuesUseField",
            "CharacteristicValues",
            "ObjectField",
            "TypeField",
            "ValueField",
            "MultipleValuesKeyField",
            "MultipleValuesOrderField",
        ];
        let mut cursor = 0;
        for name in ordered {
            cursor += xml[cursor..].find(name).unwrap();
        }
    }

    let family = OwnerGraphFamily::ChartOfCharacteristicTypes;
    let slot = characteristics_slot(family.into());
    let invalid = collection(&item(
        "4",
        "00000000-0000-0000-0000-000000000000",
        r#"{"S","must-not-leak"}"#,
    ));
    let mut owned_fields = vec!["0".to_owned(); family.layout().owner_field_count];
    owned_fields[slot] = invalid;
    let fields = owned_fields.iter().map(String::as_str).collect::<Vec<_>>();
    let mut diagnostic = None;
    assert!(
        decode_owner_characteristics(
            family.into(),
            &fields,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &references(),
            &mut diagnostic,
        )
        .is_none()
    );
    let diagnostic = diagnostic.unwrap();
    assert_eq!(diagnostic.family, "ChartOfCharacteristicTypes");
    assert_eq!(diagnostic.parser_stage, "characteristics_typed_item");
    assert_eq!(diagnostic.field_index, Some(50));
    assert_eq!(diagnostic.item_index, Some(0));
    assert_eq!(diagnostic.collection_role.as_deref(), Some("collection"));
    assert_eq!(diagnostic.offending_reference.as_deref(), None,);
    assert!(
        !serde_json::to_string(&diagnostic)
            .unwrap()
            .contains("must-not-leak")
    );
}

#[test]
fn characteristics_three_family_call_sites_share_decoder_and_xml_writer_seams() {
    let production = include_str!("mod.rs");
    for (start, end, family) in [
        (
            "fn parse_strict_catalog_properties_from_text",
            "fn parse_catalog_attribute_collection_indexed",
            "OwnerGraphFamily::Catalog",
        ),
        (
            "fn parse_document_properties_from_text",
            "fn parse_document_optional_object_reference",
            "OwnerGraphFamily::Document",
        ),
        (
            "fn parse_chart_of_characteristic_types_properties_from_text",
            "fn cct_pair_is",
            "OwnerGraphFamily::ChartOfCharacteristicTypes",
        ),
    ] {
        let start = production.find(start).unwrap();
        let end = production[start..]
            .find(end)
            .map(|offset| start + offset)
            .unwrap();
        let implementation = &production[start..end];
        assert!(implementation.contains("decode_owner_characteristics("));
        assert!(implementation.contains(family));
    }
    for (start, end, model, renderer) in [
        (
            "fn format_chart_of_characteristic_types_source_xml",
            "fn format_catalog_source_xml",
            "&chart.characteristics",
            "render_cct_characteristics_xml(",
        ),
        (
            "fn format_catalog_source_xml",
            "fn format_document_source_xml",
            "&catalog.characteristics",
            "render_metadata_characteristics_xml(",
        ),
        (
            "fn format_document_source_xml",
            "fn push_document_reference_collection_xml",
            "&document.characteristics",
            "render_metadata_characteristics_xml(",
        ),
    ] {
        let start = production.find(start).unwrap();
        let end = production[start..]
            .find(end)
            .map(|offset| start + offset)
            .unwrap();
        let writer = &production[start..end];
        assert!(writer.contains(renderer));
        assert!(writer.contains(model));
    }
    assert!(!production.contains("fn push_document_characteristics_xml"));
}

/// Builds a bare `FormChildItem` of the given tag for XML-order regression tests.
///
/// The record is the same minimal tooltip-representation shape the surrounding
/// tests reuse; every property under test is set explicitly afterwards.
fn form_child_item_for_order_test(tag: &'static str) -> FormChildItem {
    let mut item = parse_tooltip_representation_field_for_test(
        &tooltip_representation_field_record_for_test("37", "2", 59, "3", "{1,0}"),
    );
    item.tag = tag;
    item.tooltip_representation = None;
    item
}

fn assert_xml_order(xml: &str, expected: &[&str]) {
    let mut previous = 0usize;
    for needle in expected {
        let at = xml
            .find(needle)
            .unwrap_or_else(|| panic!("missing {needle} in {xml}"));
        assert!(previous <= at, "expected {expected:?} in order, got {xml}");
        previous = at;
    }
}

#[test]
fn form_field_default_item_trails_visible_and_user_visible() {
    // UT 11.5.27.75 native tree: `Visible`/`UserVisible` precede `DefaultItem`
    // on every control kind that carries them (`LabelField` 7/68 co-occurrences,
    // `InputField` 1/6, `CheckBoxField` 1/1) with no counter-example.
    for tag in ["LabelField", "InputField", "CheckBoxField"] {
        let mut item = form_child_item_for_order_test(tag);
        item.visible = Some(false);
        item.user_visible = Some(FormRightsSetting {
            common: false,
            role_values: Vec::new(),
        });
        item.default_item = Some(true);
        let xml = format_form_child_item_xml(&item, 1, false);
        assert_xml_order(
            &xml,
            &["<Visible>false</Visible>", "<UserVisible>", "<DefaultItem>"],
        );
    }
}

#[test]
fn form_label_field_hiperlink_trails_the_stretch_pair() {
    // UT 11.5.27.75 native tree, `LabelField`: `HorizontalStretch`<`Hiperlink`
    // 98 co-occurrences, `VerticalStretch`<`Hiperlink` 5, `AutoMaxHeight` 3 and
    // `MaxHeight` 2, with no counter-example, while `Hiperlink` still precedes
    // `TextColor` (28), `Font` (9) and `BackColor` (5).
    let mut item = form_child_item_for_order_test("LabelField");
    item.auto_max_height = Some(false);
    item.max_height = Some("4".to_string());
    item.horizontal_stretch = Some(true);
    item.vertical_stretch = Some(true);
    item.hiperlink = Some(true);
    item.text_color = Some("style:FormTextColor".to_string());
    let xml = format_form_child_item_xml(&item, 1, false);
    assert_xml_order(
        &xml,
        &[
            "<AutoMaxHeight>false</AutoMaxHeight>",
            "<MaxHeight>4</MaxHeight>",
            "<HorizontalStretch>true</HorizontalStretch>",
            "<VerticalStretch>true</VerticalStretch>",
            "<Hiperlink>true</Hiperlink>",
            "<TextColor>style:FormTextColor</TextColor>",
        ],
    );
}

#[test]
fn form_button_width_trails_default_button_and_skip_on_input() {
    // Native `Button` order is `… DefaultButton SkipOnInput Enabled DefaultItem
    // Width …` (43/38/2 co-occurrences, no counter-example).
    let mut item = form_child_item_for_order_test("Button");
    item.default_button = Some(true);
    item.skip_on_input = Some(true);
    item.enabled = Some(false);
    item.default_item = Some(true);
    item.width = Some("10".to_string());
    let xml = format_form_child_item_xml(&item, 1, false);
    assert_xml_order(
        &xml,
        &[
            "<DefaultButton>true</DefaultButton>",
            "<SkipOnInput>true</SkipOnInput>",
            "<Enabled>false</Enabled>",
            "<DefaultItem>true</DefaultItem>",
            "<Width>10</Width>",
        ],
    );
}

